WITH payload AS (SELECT $archive_payload$[{"id":"b68ecc17-920f-5db7-9182-454780ae7142","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب احلبوب احملظورة واحلشيش املخدر وقضيب صناعي -إقرار املدعى عليه -ثبوت اإلدانه بإقرار املدعى عليه - تعزير بالسجن واجللد واالبعاد عن الباد.","document_number":"3423184","case_number":"349847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"مخدرات -تهريب احلبوب احملظورة واحلشيش املخدر وقضيب صناعي -إقرار املدعى عليه -ثبوت اإلدانه بإقرار املدعى عليه - تعزير بالسجن واجللد واالبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3423184 :‬تاريخه‪1434/1/26:‬هـ‬\n                         ‫رقم الدعوى‪349847 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34185512‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n    ‫مخــدرات ‪ -‬تهريــب احلبــوب احملظــورة واحلشــيش املخــدر وقضيــب‬\n    ‫صناعــي ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت اإلدانــه بإقــرار املدعــى عليــه ‪-‬‬\n                            ‫تعزيــر بالســجن واجللــد واالبعــاد عــن البــاد‪.‬‬\n\n\n\n\n    ‫الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                    ‫مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ ‪.‬‬\n\n\n\n\n    ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بتهريــب املخــدرات واحلشــيش‬\n    ‫املخــدر واحلبــوب احملظــورة «ترامــادول»‪ ،‬بقصــد الكســب املــادي‬\n    ‫وتهريــب القضيــب الصناعــي‪ ،‬حيــث مت القبــض علــى املدعــى عليــه‬\n    ‫وبحوزتــه حبــوب الترامــادول واحلشــيش املخــدر ‪ ،‬اعتــراف املدعــى عليــه‬\n    ‫مبــا نســب إليــه‪ ،‬مت القبــض علــى املدعــى عليــه وبحوزتــه املخــدرات‬\n    ‫وقضيــب صناعــي‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة‬\n    ‫املضبوطــة علــى احلشــيش والترامــادول‪ ،‬لــذا طلب املدعــى العام باحلكم‬\n    ‫علــى املدعــى عليــه بعقوبــه تعزيريــة بحقــه لقــاء مــا أســند إليــه‪ ،‬وبعقوبــة‬\n    ‫تعزيريــة لقــاء حيازتــه القضيــب الصناعــي‪ ،‬وبعقوبــة تعزيريــة بحقــه‬\n    ‫لقــاء تســتره علــى مصــدر مــا ضبــط معــه‪ ،‬حكمــت احملكمــة بثبــوت‬\n‫‪5‬‬\n\f‫إدانــة املدعــى عليــه بتهريــب احلبــوب املخــدرة وقطعــة احلشــيش لقصــد‬\n‫التعاطــي‪ ،‬قــررت احملكمــة احلكــم علــى املدعــى عليــه بالســجن عشــرة‬\n‫أشــهر لتهريــب الترامــادول وثالثــة أشــهر لتهريــب القضيــب الصناعــي‬\n‫وجلــده خمســن جلــدة واإلبعــاد عــن البــاد وعــدم الســماح لــه بالعــودة‬\n‫مــرة أخــرى بعــد انتهــاء محكوميتــه‪ ،‬قــرر املدعــى عليــه عــدم قناعتــه‬\n       ‫باحلكــم‪ ،‬ومت تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 349847‬وتاريــخ ‪1434/01/06‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3444742‬وتاريــخ ‪1434/01/06‬ه ـ ففــي يــوم الثالثاء‬\n‫املوافــق ‪1434/01/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ ...‬وادعــى علــى ‪ ...‬البالــغ مــن العمــر (‪ )47‬عام ـ ًا‬\n‫مصــري اجلنســية مبوجــب جــواز ســفر رقــم (‪ ).....‬متــزوج متعلــم املهنــة‬\n‫مديــر مبيعــات يقيــم مبدينــة الريــاض أوقــف بتاريــخ ‪1433/10/14‬ه ـ‬\n‫وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف‬\n‫رقــم (ه ـ ر‪ )105240/5/1‬وتاريــخ ‪1433/10/23‬ه ـ اســتناد ًا للقــرار‬\n‫الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪)112‬‬\n‫مــن نظــام اإلجــراءات اجلزائيــة حيــث أنــه بتاريــخ ‪1433/10/14‬ه ـ قبض‬\n‫علــى املذكــور مــن قبــل أحــد موظفــي جمــرك مطــار امللــك خالــد الدولــي‬\n‫بالريــاض أثــر قدومــه مــن جمهوريــة مصــر العربيــة عبــر اخلطــوط ‪.....‬‬\n‫علــى الرحلــة رقــم (‪ ).....‬القادمــة مــن القاهــرة وبتفتيــش أمتعتــه عثــر معــه‬\n                                                                                       ‫‪6‬‬\n\f    ‫يف حقيبتــه اليدويــة علــى ماعــدده (‪ )123‬مائــة وثالثــة وعشــرون حبــة‬\n    ‫مــن حبــوب الترامــادول املهدئــة احملظــورة كمــا عثــر معــه علــى (قضيــب‬\n    ‫صناعــي) كان ظاهــر ًا باحلقيبــة مت وضعــه داخــل كيــس ومت العثــور‬\n    ‫علــى أربــع شــرائح بداخــل احلقيبــة اليدويــة وعنــد إحالتهــا ملنــدوب وزاره‬\n    ‫اإلعــام أفــاد باحتــواء أحــد هــذه الشــرائح املضبوطــة علــى مــواد مخلــة‬\n    ‫بــاآلداب كماعثــر علــى (‪ )1‬حبــة واحــدة ســوداء اللــون غيــر معروفــه‬\n    ‫وعثــر داخــل احلقيبــة اليدويــة علــى بكــت دخــان وعنــد تفتيشــه عثــر‬\n    ‫بداخلــه علــى قطعتــن صغيــرة بنيــة اللــون يشــتبه أن تكــون مــن مــادة‬\n    ‫احلشــيش كمــا عثــر بداخــل ظــرف أبيــض داخــل الشــنطة علــى قطعــة‬\n    ‫بنيــة يشــتبه أن تكــون مــن مــادة احلشــيش بلــغ وزن الكميــة إجمــاال‬\n    ‫(‪ )4.4‬أربــع جرامــات وأربعــة أعشــار اجلــرام ‪ .‬وقــد أثبــت التقريــر‬\n    ‫الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n    ‫الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪/9610‬س) لعــام ‪1433‬ه ـ‬\n    ‫ايجابيــة عينــة القطــع املضبوطــة ملــادة احلشــيش وهــو مــن املــواد املخــدرة‬\n    ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n    ‫واملؤثــرات العقليــة كمــا أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n    ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n    ‫رقــم (‪/9611‬س) لعــام ‪1433‬ه ـ احتــواء عينــة احلبــوب املضبوطــة ملــادة‬\n    ‫الترامــادول وهــو مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (هــ)‬\n    ‫مــن النظــام املشــار إليــه وباســتجوابه أفــاد بصحــة واقعــة الضبــط حيــث‬\n    ‫انــه كان قادم ـ ًا مــن جمهوريــة مصــر العربيــة وعنــد نزولــه ملطــار امللــك‬\n    ‫خالــد بالريــاض وبتفتيــش أمتعتــه عثــر علــى ماعــدده (‪ )123‬مائــة وثالثــة‬\n    ‫وعشــرون حبــة مــن احلبــوب املهدئــة كمــا عثــر علــى علبــه ســجائر (‪)......‬‬\n\n\n‫‪7‬‬\n\f‫بهــا ثــاث قطــع مــن احلشــيش املخــدر أفــاد بأنهــا تعــود ألحــد أصدقــاء‬\n‫يف مصــر نســيها معــه يف حقيبتــه كمــا أقــر بــأن احلبــوب املضبوطــة‬\n‫معــه يســتخدمها كونــه مريــض ولديــه وصفــة طبيــة بذلــك كمــا أقــر‬\n‫بحيــازة (القضيــب الصناعــي) وأن هــذا خطــأ منــه إلحضــاره القضيــب‬\n‫الصناعــي حيــث أحضــر أغــراض نســائية وال يعلــم مابداخلهــا كمــا‬\n‫أقــر بحيازتــه للذاكــرة ‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن توجيــه‬\n‫االتهــام ل ‪ ....‬بتهريــب ماعــدده (‪ )123‬مائــة وثــاث وعشــرون حبــة مــن‬\n‫حبــوب الترامــادول احملظــورة و(‪ )3‬قطــع مــن احلشــيش املخــدر بلــغ وزنهــا‬\n‫(‪ )4.4‬أربعــة جرامــات وأربعــة أعشــار اجلــرام بقصــد التعاطــي املجــرم‬\n‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n          ‫وتســتره علــى مصــدر مــا مت ضبطــه املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 -:‬مــا تضمنــه اعترافــه حتقيق ـ ًا‬\n‫ا علــى الصفحــات رقــم ( ) مــن دفتــر التحقيــق‬       ‫املنــوه عنــه املــدون تفصيـ ً‬\n‫املرفــق لفــه رقــم ( ) ‪ -2 .‬مــا تضمنــه محضــر الضبــط املنــوه عنــه املرفــق‬\n‫لفــه رقــم ( ) ‪ -3 .‬مــا تضمنــه محضــر البــاغ املنــوه عنــه املدونــة علــى‬\n‫الصفحــة رقــم ( ) مــن إجــراءات االســتدالل املرفــق لفــه ( ) ‪ -4 .‬مــا‬\n‫تضمنــه التقريــران الكيميائيــان الشــرعيان املنــوه عنهمــا املرفقــان لفــه‬\n‫رقــم ( ) ‪ -5 .‬مــا ورد بخطــاب املشــرف العــام علــى مدينــة امللــك ســعود‬\n‫الطبيــة رقــم (‪ )51789‬وتاريــخ ‪1433/11/30‬ه ـ ‪ .‬وببحــث ســوابقه لــم‬\n‫يعثــر لــه علــى ســوابق حتــى تاريخــه‪ .‬وحيــث أن مــا أقــدم عليــه املذكــور‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا ‪ ،‬لــذا اطلــب إثبــات إدانتــه مبــا‬\n                                             ‫أســند إليــه واحلكــم عليــه باآلتــي‪-:‬‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫‪ -1‬بعقوبــة تعزيريــة بحقــه وفق ـ ًا للفقــرة (األولــى) مــن املــادة (‪ )41‬مــن‬\n    ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه لقــاء مــا‬\n                                                                          ‫أســند إليــه ‪.‬‬\n    ‫‪ -2‬إبعــاده إلــى خــارج اململكــة بعــد تنفيــذ عقوبتــه وعــدم الســماح لــه‬\n    ‫بالعــودة مــرة أخــرى وفق ـ ًا للفقــرة (الثانيــة) مــن املــادة (‪ )56‬مــن النظــام‬\n                                                                         ‫املشــار إليــه ‪.‬‬\n                          ‫‪ -3‬بعقوبة تعزيرية لقاء حيازته (للقضيب الصناعي) ‪.‬‬\n              ‫‪ -4‬بعقوبة تعزيرية بحقه لقاء تستره على مصدر ما ضبط معه ‪.‬‬\n    ‫وبعرضــه علــى املدعــى عليــه صــادق علــى العثــور علــى قطعــة احلشــيش‬\n    ‫املخــدر واحلبــوب احملظــورة املشــار إليهــا والقضيــب الصناعــي يف حقيبته‬\n    ‫ا إننــي لــم‬‫يف مطــار امللــك خالــد بعــد حضــوره مــن مصــر وأضــاف قائ ـ ً‬\n    ‫أكــن أعلــم عــن مــن وضعهــا يف حقيبتــي أثنــاء وجــودي يف مصــر وقــد مت‬\n    ‫االطــاع علــى التقريــر الكيمــاوي فوجدتــه مطابــق ملــا ذكــره املدعــي‬\n    ‫العــام فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة فقــد ثبــت لــدي إدانــة‬\n    ‫املدعــى عليــه بتهريــب احلبــوب احملظــورة وقطعــة احلشــيش املشــار إليــه‬\n    ‫القصــد التعاطــي والقضيــب الصناعــي وحكمــت عليــه مبوجــب املــادة‬\n    ‫الواحــدة واألربعــون بــأن يســجن عشــرة أشــهر كمــا حكمــت عليــه لقــاء‬\n    ‫تهريبــه القضيــب الصناعــي بــأن يســجن ثالثــة أشــهر ويكــون ســجنه‬\n    ‫ابتــداء مــن إيقافــه كمــا حكمــت بجلــده خمســن جلــدة دفعــة واحــدة‬\n    ‫لقــاء تهريــب القضيــب الصناعــي كمــا حكمــت بإبعــاده لبــاده بعــد‬\n    ‫انتهــاء محكوميتــه ومنعــه مــن دخــول ململكــة تطبيقـ ًا للمــادة السادســة‬\n    ‫واخلمســن مــن نظــام مكافحــة املخــدرات ويشــمل احلكــم تســتره علــى‬\n    ‫مصــدر مــا ضبــط معــه وبعرضــه عليهمــا قــررا املدعــي العــام واملدعــى‬\n\n\n‫‪9‬‬\n\f‫عليــه عــدم القناعــة وطلــب املدعــى عليــه نســخة مــن احلكــم لتقــدمي‬\n‫الئحتــه اإلعتراضيــة أمــا املدعــي العــام فاكتفــى بالئحــة الدعــوى‬\n‫العامــة الئحــة إعتراضيــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم حــرريف ‪1434/1/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافق‪1434/01/26‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر ‪ ....‬ومت تســليمه نســخة مــن قــرار احلكــم لتقــدمي الئحتــه‬\n‫االعتراضيــة وأفهــم بــأن لــه مــدة ثالثــون يوم ـ ًا مــن تاريــخ اليــوم إن‬\n‫لــم يقــدم الئحتــه ســيرفع احلكــم حملكمــة االســتئناف دون الئحــة‬\n‫إعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافــق‪ 1434/01/26‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر ‪ .......‬ومت تســليمه نســخة مــن قــرار احلكــم لتقــدمي الئحتــه‬\n‫االعتراضيــة وأفهــم بــأن لــه مــدة ثالثــون يومــا مــن تاريــخ اليــوم إن‬\n‫لــم يقــدم الئحتــه ســيرفع احلكــم حملكمــة االســتئناف دون الئحــة‬\n‫إعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/26‬ه ـ‬\n‫احلمــد هلل وحــده ‪...‬وبعــد فقــد اطلعنا نحن قضــاة الدائرة اجلزائية الرابعة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم ‪34/44742‬وتاريــخ ‪1434 /3/15‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ ‪ ....../‬املســجل‬\n‫برقــم ‪3423184‬وتاريــخ ‪1434/1/26‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n\n\n                                                                                  ‫‪10‬‬\n\f     ‫ضــد ‪(......../‬مصــري اجلنســية) يف قضيــة مخــدرات علــى النحــو املوضــح‬\n     ‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مدونبــه ‪،‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قــررت الدائــرة‬\n     ‫باألكثريــةا ملصادقــة علــى احلكــم‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                     ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪11‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":5,"source_page_end":11,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f3f2c15b19600ac44a856a56133ea4df77beac9708b4e3042770bab1af8c5c3c","normalized_text_hash":"dad9eb17fe7cca50e729b525ad6b3884b4cff12662150877fc67dea0b0d7e5fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p5-3423184"},{"id":"d7699d7b-7c8b-5fc2-9426-30d78e690860","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب ( ماريجوانا ) -ترويج ( ماريجوانا ) -تع اط ي ( ماريجوانا ) -رجوع عن إقرار -مقاومة قوات الشرطة -ثبوت إدانة -تشديد العقوبة -تعزير بالسجن واجللد والغرامة واالبعاد عن الباد ومصادرة اجلوال والشريحة .","document_number":"33237852","case_number":"3265958","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/10","year":"1434","subject":"مخدرات -تهريب ( ماريجوانا ) -ترويج ( ماريجوانا ) -تع اط ي ( ماريجوانا ) -رجوع عن إقرار -مقاومة قوات الشرطة -ثبوت إدانة -تشديد العقوبة -تعزير بالسجن واجللد والغرامة واالبعاد عن الباد ومصادرة اجلوال والشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33237852 :‬تاريخه‪1434/5/10 :‬هـ‬\n                    ‫رقم الدعوى‪3265958 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34362674‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تهريــب ( ماريجوانــا ) ‪ -‬ترويــج ( ماريجوانــا ) ‪ -‬تعـ ــاط ــي‬\n‫( ماريجوانــا ) ‪ -‬رجــوع عــن إقــرار ‪ -‬مقاومــة قــوات الشــرطة ‪ -‬ثبــوت‬\n‫إدانــة ‪ -‬تشــديد العقوبــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واالبعــاد‬\n                               ‫عــن البــاد ومصــادرة اجلــوال والشــريحة ‪.‬‬\n\n\n\n\n               ‫‪ -‬قوله تعالى‪ ( :‬وال تفسدوا يف األرض بعد إصالحها )‪.‬‬\n                     ‫‪ -‬قوله تعالى‪ ( :‬إن اهلل اليصلح عمل املفسدين )‪.‬‬\n                                                                ‫‪ -‬حد املسكر ‪.‬‬\n‫‪ -‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )37‬والفقــرة (‪)1‬‬\n‫مــن املــادة (‪ )53‬واملــادة (‪ )62‬واملــادة (‪ )64‬مــن نظــام مكافحــة املخــدرات‬\n                                                           ‫واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهمــا بتهريــب وترويــج املخــدرات‬\n‫‪ -‬ماريجوانــا‪ -‬بقصــد الكســب املــادي‪ ،‬مت القبــض علــى املدعــى عليــه‬\n‫بغرفتــه وبحوزتــه نبــات املاريجوانــا أقــر املدعى عليــه األول صفة الترويج‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n\n                                                                                   ‫‪12‬‬\n\f     ‫املاريجوانــا ‪ ،‬طلــب املدعــي العــام باحلكــم علــى املدعــى عليهمــا بعقوبــة‬\n     ‫القتــل تعزيــرا ‪ ،‬ومصــادرة جواليهمــا ‪ ،‬حكمــت احملكمــة بثبــوت إدانــة‬\n     ‫املدعــى عليهمــا بتنــاول كل منهمــا نبــات املاريجوانــا ‪ ،‬وثبتــوت إدانــة‬\n     ‫املدعــى عليــه الثانــي بتهريــب نبــات املاريجوانــا وإدانتــه باحليــازة بقصــد‬\n     ‫االجتــار والتعاطــي قــررت احملكمــة علــى املدعــى األول بالســجن ملــدة‬\n     ‫خمــس ســنوات وجلــده خمســمائة جلــدة تعزيــرا للقرائــن والتهــم‪ ،‬وتعزيــر‬\n     ‫املدعــى عليــه الثانــي بالســجن ملــدة عشــر ســنوات تبــدأ فتــرة الســجن مــن‬\n     ‫تاريــخ القبــض علــى كل واحــد منهمــا‪ ،‬وجلــد كل منهمــا ســبعمائة‬\n     ‫جلــدة ويكــون اجللــد علــى دفعــات متســاوية كل دفعــة خمســون جلــدة‬\n     ‫وبــن كل دفعــة عشــرة أيــام علــى أن تنفــذ أربــع دفعــات مــن دفعــات‬\n     ‫اجللــد أمــام جامــع خــادم احلرمــن الشــريفني بالدمــام‪ ،‬إقامــة حــد شــرب‬\n     ‫املســكر علــى كل واحــد منهمــا بجلدهمــا ثمانــن جلــدة دفعــة واحــدة‪،‬‬\n     ‫تغــرمي املدعــى عليــه الثانــي مائــة ألــف ري ــال تــؤول خلزينــة الدولــة العامــة‪،‬‬\n     ‫إبعــاد املدعــى عليهمــا مــن البــاد بعــد اســتيفاء مــا لهمــا ومــا عليهمــا مــن‬\n     ‫حقــوق‪ ،‬مصــادرة جــوال املدعــى عليــه الثانــي وعــدم صــرف الشــريحة لــه‬\n     ‫مــرة أخــرى‪ ،‬اعتــراض املدعــى عليهمــا‪ ،‬مت تصديــق احلكــم مــن قبــل‬\n                                                                  ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدى د‪ .......................‬و‪ ...........‬القضــاة يف‬\n     ‫احملكمــة العامــة بالدمــام بنــاء علــى املعاملــة احملالــة لنــا منفضيلة رئيس‬\n     ‫احملكمــة العامــة بالدمــام برقم ‪ ...........‬وتاريخ ‪1432/03/04‬هـ املقيدة‬\n     ‫باحملكمــة برقــم ‪ ...........‬وتاريــخ ‪1432/03/04‬ه ـ ففــي يــوم االثنــن‬\n‫‪13‬‬\n\f‫املوافــق ‪1432/04/02‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬وفيهــا حضر‬\n‫املدعــي العــام ‪ ...........‬وحضــر حلضــوره املدعــى عليــه الســجني ‪...........‬‬\n‫بنجالديشــي اجلنســية يحمــل اإلقامــة رقــم ‪ ...........‬وحضــر املدعــى عليــه‬\n‫الســجني ‪...........‬بنجالديشــي اجلنســية يحمــل اإلقامــة رقــم ‪...........‬‬\n‫وادعــى املدعــي العــام قائـاً‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام‬\n‫لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى املذكوريــن أعــاه باإلطــاع‬\n‫علــى محضــر البــاغ ومحضــر االنتقــال والقبــض والتفتيــش املعــد مــن‬\n‫قبــل رجــال مكافحــة املخــدرات مبحافظــة بقيــق أتضــح أنــه مت القبــض‬\n‫علــى املذكوريــن بتاريــخ ‪1431/6/7‬ه ـ بعــد توفــر معلومــات لديهــم مــن‬\n‫أحــد املصــادر الســرية تفيــد بقيــام املتهــم (‪ )...........‬بتهريــب واســتخدام‬\n‫نبــات (ماريجوانــا) علــى نطــاق واســع وتفيــد املعلومــات بــأن املتهــم‬\n‫املذكــور (‪ )...........‬يســكن يف مدينــة الدمــام (حــي ‪ ).........‬وأنــه يقــوم‬\n‫بترويــج (ماريجوانــا) وأنــه حــذر جــداً‪ ،‬وقــد اســتعد املصــدر للتعــاون مــن‬\n‫أجــل القبــض عليــه باجلــرم املشــهود وذلــك بالشــراء منــه وقــد مت تســليم‬\n‫املصــدر مبلــغ حكومــي وقــدره (‪ )100‬مائــة ريــال وقــد متكــن املصــدر‬\n‫مــن االتصــال علــى املــروج (‪ )...........‬علــى جوالــه رقــم (‪ )...........‬وطلــب‬\n‫املصــدر منــه نبــات (ماريجوانــا) املخــدر فوافــق علــى ذلــك وطلــب مــن‬\n‫املصــدر احلضــور إلــى حــي (‪ )....‬وقــد أفــاد املصــدر أنــه ســوف يذهــب‬\n‫الىســكن املتهــم (‪ )...........‬وقــد مت تفتيــش املصــدر تفتيشـ ًا دقيقـ ًا بعدمــا‬\n‫مت تزويــده باملبلــغ احلكومــي وقــد مت تكليــف أحــد أفــراد الفرقــة‬\n‫مبرافقــة املصــدر أثنــاء عمليــة الشــراء‪ .‬وبعــد االنتقــال الــى ســكن املتهــم‬\n‫(‪ )...........‬شــاهد رجــال األمــن حيــث كان حــذر ًا جــد ًا وحــاول الهــرب‬\n‫ومت القبــض عليــه ومت تفيــش الغرفــة اخلاصــة بــه كونــه يســكن غرفــة‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫عــزاب وقــد أتضــح بــأن للمذكــور غرفتــن ومت تفتيــش الغرفــة األولــى‬\n     ‫ولــم يعثــر بهــا علــى شــيء وبتفتيــش الغرفــة الثانيــة وهي قريبة مــن الغرفة‬\n     ‫األولــى عثــر بالغرفــة الثانيــة علــى كرتــون بحجــم الكــف يســتخدم يف‬\n     ‫حفــظ املالبــس الداخليــة حيــث يســتخدم للتمويــه علــى رجــال مكافحــة‬\n      ‫املخــدرات وهــو قــد اســتخدم يف تهريــب نبــات (ماريجوانــا) احملظــورة‪.‬‬\n     ‫وقــد اتضــح أنــه يوجــد بالكرتــون (نبــات أخضــر) ماريجوانــا احملظــورة‬\n     ‫بلــغ وزنــه ( ‪ )105.5‬مائــة وخمســة جــرام وخمســة مــن العشــرة مــن اجلــرام‬\n     ‫وكذلــك عثــر يف نفــس الغرفــة علــى عــدد (‪ )23‬ثالثة وعشــرين قصاصة‬\n     ‫ورقيــة بداخلهــا (نبــات اخضــر) نبــات ماريجوانــا املخــدرة بلــغ إجمالــي‬\n     ‫وزنهــا (‪ )62.5‬اثنــان وســتون جــرام وخمســة مــن العشــرة مــن اجلــرام وهــي‬\n     ‫جاهزةومعــدة للترويــج ‪ ،‬وكذلــك عثــر يف نفــس الغرفــة علــى كيــس‬\n     ‫واحــد عثــر بداخلــه علــى (نبــات اخضــر) وهــو نبــات ماريجوانــا املخــدرة‬\n     ‫بلــغ وزنــه (‪ )163.6‬مائــة وثالثــة وســتون جــرام وســتة مــن العشــرة مــن‬\n     ‫اجلــرام ‪ ،‬وكذلــك عثــر علــى كميــة كبيــرة جــد ًا مــن األوراق تســتخدم‬\n     ‫يف لعــب القمــار وقــد إعتــرف املتهــم (‪ )...........‬للفرقــة بأنــه ســبق وأن‬\n     ‫تقابــل مــع املتهــم (‪ )...........‬يف بنجالديــش وأتفقــا علــى أن يقــوم هــو‬\n     ‫(‪ )...........‬بتهريــب نبــات ماريجوانــا املخــدرة إلــى اململكــة العربيــة‬\n     ‫الســعودية عــن طريــق مطــار امللــك فهــد بالدمــام ‪ ،‬وأفــاد أنــه قــال للمتهــم‬\n     ‫(‪ )...........‬أنــه خايــف أن يتــم القبــض عليــه باملطــار ‪ ،‬وقــال لــه‪...........‬‬\n     ‫التخــاف اذا قدمــت الــى اململكــة العربيةالســعودية ســوف أقــوم بتســهيل‬\n     ‫ا قــام هــو (‪ )...........‬بتهريــب كميــة مــن نبــات ماريجوانــا‬  ‫مهمتــك وفع ـ ً‬\n     ‫املخــدرة وقــام (‪ )...........‬باســتقباله يف املطــار وأخــذه معــه يف ســيارته‬\n     ‫وذهبــوا ســوي ًا إلــى مقــر ســكنه يف ‪.........‬وبعدذلــك تقاســموا الكميــة‬\n\n\n‫‪15‬‬\n\f‫بينهمــا بالنصــف وأقــر أنــه يقــوم بترويــج نبــات ماريجوانــا املخــدرة بقصد‬\n‫اإلجتــار وقــد اســتعد املتهــم (‪ )...........‬للشــراء مــن املتهــم (‪ )...........‬مببلــغ‬\n‫(‪ )100‬مائــة ريــال ومتكــن املتهــم (‪ )...........‬مــن االتصــال علــى جــوال‬\n‫‪ ...........‬الــذي يحمــل الرقــم (‪ )...........‬وكان ذلــك علــى مســمع مــن‬\n‫أفــراد الفرقــة وطلــب مــن املتهــم (‪ )...........‬نبــات ماريجوانــا املخــدرة‬\n‫وســأل املتهــم (‪ )...........‬املتهــم (‪ )...........‬عــن الكميــة التيلديــه وأخبــر‬\n                                   ‫(‪ )...........‬بأنهــا قــد نفــذت كلهاوقــال املتهــم‬\n‫‪...........‬للمتهــم (‪ )...........‬ســوف أحضــر لــك عنــد ســكنك وأعطيــك‬\n‫ماطلبــت ومت تكليــف أحــد أفــراد الفرقــة مبرافقة املتهــم (‪ )...........‬أثناء‬\n‫عمليــة الشــراء وعنــد الوصــول الــى ســكن (‪ )......‬كان املتهــم (‪)...........‬‬\n‫وأشــار لــه املتهــم (‪ ) ...........‬وخوفـ ًا مــن انكشــاف الفرقــة جــرى التأكد‬\n‫مــن هويــة املتهــم (‪ )...........‬وقــد ظهــر عليــه اخلــوف واالرتبــاك وعنــد‬\n‫التأكــد مــن هويتــه قــام بالهــرب ومت القبــض عليــه وقــد قــام مبقاومــة‬\n‫الفرقــة مقاومــة شــديدة عنــد القبــض عليــه وقــد نتــج عــن ذلــك إصابــات‬\n‫وجــروح ســطحية ببعــض أفــراد الفرقــة‪ .‬وبتفتيــش الغرفــة التي ســكنبها‬\n‫يف ‪.........‬عثر بها على أوراق كثيرة عليها رســوم وطالســم تســتخدم يف‬\n‫لعــب القمــار ‪ ،‬وكذلــك عثــر علــى حــوالت بنكيــة مببلــغ خمســة عشــر‬\n‫الــف ريــال (‪ )15000‬ريــال وحوالــة مببلــغ (‪ )5000‬خمســة االف ريــال ‪،‬‬\n‫وقــد إعتــرف ألفــراد الفرقــة مبــا نســب إليــه مــن قيامــه بعمليــة الترويــج‬\n‫املــواد املخــدرة كمــا أنــه مت القبــض علــى بعــض االشــخاص يف قضيــة‬\n‫حيــازة املاريجوانــا وأفــاد بأنهــم حصلــوا عليهــا مــن املتهمــن املذكوريــن‬\n‫‪ ،‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ ).........‬وتاريــخ‬\n‫‪1431/6/25‬ه ـ إيجابيــة جميــع عينــات ماضبــط مــن نبــات أخضــر ملــادة‬\n\n\n                                                                                              ‫‪16‬‬\n\f     ‫(املاريجوانــا) املخــدرة املدرجــة يف اجلــدول ( ‪ ) 2‬فئــة ( ب ) مــن نظــام‬\n     ‫مكافحــة املخــدرات وباســتجواب املتهــم (‪ )...........‬أقــر أنــه مت القبــض‬\n     ‫عليــه مــن قبــل رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات بعــد‬\n     ‫قيامــه بتهريــب حوالــي نصــف كيلــو مــن نبــات املاريجوانــا احملظــورة من‬\n     ‫بنجالديــش عــن طريــق مطــار امللــك فهــد بالدمــام وأفــاد أنــه احضرهــا‬\n     ‫داخــل شــنطة حيــث قــام املتهــم (‪ )...........‬بالتنســيق مــع شــخص يف‬\n     ‫بنجالديــش وأعطــاه املاريجوانــا وقــام هــو (‪ )...........‬بتهريبهــا وكان‬\n     ‫‪...........‬باســتقباله يف املطــار وأعطــاه كرتونــن مــن نبــات املاريجوانــا‬\n     ‫مقابــل تهريــب املخــدرات وإحضــاره الــى الدمــام كمــا أقــر أنــه قــام‬\n     ‫بالتفــاوض علــى ترويــج نبــات املاريجوانــا احملظــورة وأقــر أنــه بتفتيــش‬\n     ‫غرفتــه عثــر بهــا علــى كرتــون بحجــم الكــف مختــوم لشــركة مصنعــة‬\n     ‫للمالبــس الداخليــة وبداخلــه كيــس نبــات املاريجوانــا احملظــورة بلــغ‬\n     ‫وزنــه (‪ )105.5‬مائــة وخمســة جــرام وخمســة مــن العشــرة مــن اجلــرام‬\n     ‫كمــا أقــر أنــه عثــر علــى عــدد (‪ )23‬ثالثــة وعشــرين قصاصــة ورقيــة‬\n     ‫بداخلهــا نبــات املاريجوانــا احملظــورة بلــغ وزنهــا (‪ )62.5‬اثنــان وســتون‬\n     ‫جــرام وخمســة مــن العشــرة مــن اجلــرام وكذلــك عثــر يف غرفتــه‬\n     ‫علــى كيــس بالســتيك بداخلــه نبــات املاريجوانــا احملظــورة بلــغ وزنــه‬\n     ‫(‪ )163.6‬مائــة وثالثــة وســتون جــرام وســتة مــن العشــرة مــن اجلــرام وأقــر‬\n     ‫بــأن مــا مت ضبطــه مــن نبــات املاريجوانــا احملظــورة يعــود لــه ولزميلــه‬\n     ‫(‪ )...........‬وأفــاد بــأن قصدهــم مــن حيــازة نبــات املاريجوانــا الترويــج‬\n     ‫وقــد صــدق إعترافــه شــرعاًبذلك كمــا أقــر حتقيق ـ ًا أنــه قــام بترويــج‬\n     ‫نبــات املاريجوانــا احملظــورة مرتــن تقريب ـ ًا كماأقــر أنــه تفــاوض علــى‬\n     ‫ترويجهــا مــع أحــد االشــخاص مقابــل مبلــغ (‪ )100‬مائــة ريــال وهــو‬\n\n\n‫‪17‬‬\n\f‫قدســبق وأن روج علــى ذلــك الشــخص الــذي تفــاوض معــه عــن طريــق‬\n‫الهاتــف ‪ ،‬كمــا أقــر أنــه قــام بتهريــب ماوزنــه (حوالــي نصــف كيلــو)‬\n‫مــن نبــات املاريجوانــا احملظــورة يف خمــس كراتــن خاصــة باملالبــس‬\n‫الداخليــة حيــث أفــاد أنــه متكــن مــن ادخالهــا عــن طريــق مطــار امللــك‬\n‫فهــد بالدمــام حيــث اســتلمها مــن شــخص قريــب للمتهــم (‪ )...........‬يف‬\n‫بنجالديــش كمــا أقــر أنــه يتعاطــى نبــات املاريجوانــا احملظــورة ‪ ،‬كمــا‬\n‫أقــر أنــه ضبــط داخــل غرفتــه علــى أوراق خاصةبلعــب القمــار وأفــاد أنــه‬\n‫اليعــرف الشــخص الــذي ســلمه املاريجوانــا يف بنجالديــش وأفــاد بــأن‬\n‫املتهــم (‪ )...........‬اســتقبله يف املطــار وأعطــاه كرتونــن مــن الكميــة‬\n‫مقابــل قيامــه بتهريــب نبــات املاريجوانــا وقدختــم أقوالــه باملصادقــة‬\n‫عليهــا‪ .‬وباســتجواب املتهــم (‪ )...........‬أقــر أنــه مت القبــض عليــه مــن قبــل‬\n‫رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات عندمــا أتصــل عليــه‬\n‫املتهــم (‪ )...........‬وطلــب منــه نبــات املاريجوانــا احملظــورة وأفــاد أنــه كان‬\n‫موجــود بالقــرب مــن غرفــة (‪ )...........‬ومت القبــض عليــه وعندمحاولــة‬\n‫القبــض عليــه حــاول الهــرب وبســؤاله عــن ســبب محاولتــه الهــرب زعــم‬\n‫أنــه كان خايــف واليعلــم انهــم رجــال أمــن وزعــم أنــه اليقــوم بترويج نبات‬\n‫املاريجوانــا احملظــورة ومبواجهتــه مبــا جــاء يف إقــرار املتهــم (‪)...........‬‬\n‫املتضمــن ان (‪ )...........‬هــو الــذي قــام بالتنســيق مــن أجــل تهريــب نبــات‬\n‫املاريجوانــا احملظــورة حيــث طلــب مــن شــخص يف بنجالديــش أن يســلم‬\n‫(نبــات املاريجوانــا) للمتهــم (‪ )...........‬وأنــه اســتقبل ‪.........‬يف مطــار امللــك‬\n‫ا اتصــل بــي ‪....‬‬   ‫فهــد بالدمــام وأمــا املدعــى عليــه ‪...........‬فأجــاب قائ ـ ً‬\n‫وطلــب منــي احلضــور فحضــرت إلــى مســكنه يف حــي ‪.........‬بالدمــام‬\n‫ففوجئــت بالقبــض علــي مــن الفرقــة القابضــة وحاولــت الهــرب خوف ـ ًا‬\n\n\n                                                                                           ‫‪18‬‬\n\f     ‫منهــم إذ قبــل ســاعة أو ســاعتني تهجــم شــخص علــى أخــي وأخــذ منــه‬\n     ‫ألفــي ريــال غصبـ ًا عنــه وال صحــة ملــا ذكــره املدعــي العــام مــن تنســيقي‬\n     ‫مــع ‪ .........‬لتهريــب احلشــيش املخــدر وأمــا أوراق القمــار فليســت عائــدة‬\n     ‫لــي وهــي عائــدة لشــخص آخــر يســكن معــي وأنــا أتعاطــى نبــات‬\n     ‫املاريجوانــا احملظــور املخــدرة وأمــا اجلــوال ‪ ...........‬ويحمــل الشــريحة رقــم‬\n     ‫‪.........‬فعائــد لــي وهــو مــن نــوع ‪ ....‬ورقــم الهاتــف اجلــوال ‪ ...........‬هكــذا‬\n     ‫اجــاب وإلحضــار الفرقــة القابضــة علــى املدعــى عليهمــا رفعــت اجللســة‬\n     ‫ويف جلســة أخــرى حضــر املدعــي العــام ‪.........‬ولــم يحضــر الســجينان‬\n     ‫كل مــن ‪...........‬و ‪...........‬بنجالديشــيي اجلنســية ولــم يحضــر املترجمــن‬\n     ‫وال املزكيــن لهمــا وحضــرت الفرقــة القابضــة ويف جلســة أخــرى حضــر‬\n     ‫املدعــي العــام ‪...........‬ولــم يحضــر كل مــن الســجينني‪...........‬و ‪...........‬‬\n     ‫بنجالديشــيي اجلنســية ولــم يحضــر املترجــم بلغتهمــا وال املزكيــن لهمــا‬\n     ‫وحضــرت الفرقــة القابضــة وهــم كل مــن ‪...........‬ســجل مدنــي ‪...........‬‬\n     ‫و‪...........‬ســجل مدنــي ‪ ...........‬و ‪...........‬ســجل مدنــي ‪ ...........‬و ‪...........‬‬\n     ‫ســجل مدنــي رقــم ‪...........‬وباستشــهاد الشــهود شــهدوا قائلــن نشــهد‬\n     ‫بــأن جميــع مــا ورد يف محضــر القبــض والتفتيــش أنــه صحيــح وقــد‬\n     ‫زكــى الشــهود كل مــن ‪...........‬و ‪...........‬وبعــد تعريفهــم بالشــهود قــررا‬\n     ‫قائلــن نشــهد انهــم عــدول ثقــات ورفعــت اجللســة لإلطــاع علــى اعتــراف‬\n     ‫املدعــى عليهمــا ويف جلســة أخــرى حضــر الســجينان ‪...........‬و‪...........‬‬\n     ‫املثبــت يف اجللســات الســابقة صفتهمــا وحضــر كل مــن املترجــم املوظــف‬\n     ‫باحملكمــة ‪...........‬باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n     ‫الدمــام برقــم ‪ ...........‬يف ‪1431 /05 /12‬ه ـ واملترجــم املتعــاون ‪...........‬‬\n     ‫بنجالديشــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن الدمــام برقــم‬\n\n\n‫‪19‬‬\n\f‫‪ ...........‬وزكاهمــا بعــد التعريــف بهمــا ‪...........‬هنــدي اجلنســية بنوجــب‬\n‫اإلقامــة الصــادرة مــن الدمــام برقــم ‪ ...........‬بقولــه أشــهد أن ‪...........‬و‬\n‫‪...........‬ثقتــان ويف هــذه اجللســة مت قــراءة شــهادة شــهود الفرقــة القابضــة‬\n‫املدونــة يف اجللســة الســابقة علــى املدعــى عليهمــا كل واحــد منهمــا‬\n‫علــى انفــراد فأجــاب بقولــه كل ماجــاء يف شــهادة الفرقــة القابضــة مــن‬\n‫إعتــرايف أمامهــم فهــو صحيــح لكنــي لــم أعتــرف بهــذا اإلعتــراف إال‬\n‫بتلقــن وإكــراه منهــم هكــذا قــرر ‪ ...........‬وأمــا املدعــى عليــه ‪...........‬‬\n‫فأجــاب بــان واقعــة القبــض علــي صحيحــه ولكــن ال صحــة ملــا ســوى‬\n‫ذلــك مــن اعتــراف ‪.........‬باننــي انســق معــه باننــي احضــر املاريجوانــا‬\n‫املخــدر مــن بنجالديــش أوإننــي اســتقبله يف املطــار عنــد قدومــه مــن‬\n‫بنجالديــش ورفعــت اجللســة لالطــاع علــى اعتــرايف املدعــى عليهمــا‬\n‫ويف جلســة أخــرى لــدي أنــا ‪ ...........‬فتحــت اجللســة مبشــاركة صاحبــي‬\n‫الفضيلــة القاضيــن بهــذه احملكمــة الشــيخ ‪...........‬و‪...........‬وبهــا حضــر‬\n‫املدعــي العــام واملدعــى عليهمــا وجــرى تــاوة مــا ُســبق ضبطــه فصادقــوا‬\n‫عليه‪.‬اهــ‪ .‬وأضــاف املدعــى عليــه األول ‪...........‬قائالً‪:‬مــا ذكــره املدعــي‬\n‫العــام يف دعــواه كلــه غيــر صحيــح عــدا أننــي أتيــت إلــى شــقته فأنــا لــم‬\n‫أقــم بالتنســيق مــع املدعــى عليــه الثانــي مــن أجــل تهريــب كميــة مــن‬\n‫بنجالديــش إلــى الســعودية ولــم أقــم باإلتفــاق معــه أيضـ ًا علــى بيــع كمية‬\n‫مــن نبــات املاريجوانــا والــذي حصــل أن املدعــى عليــه الثانــي اتصــل بــي‬\n‫وطلــب منــي القــدوم إلــى شــقته فأخبرتــه أنــي قريــب منهــا بعدهــا مت‬\n‫القبــض علــي وأنــا أســتخدم نبــات املاريجوانــا منــذ ثــاث ســنوات ولــم‬\n‫يصــدر علــي حكــم بذلك‪.‬هــذا مــاأردت إضافتــه يف جوابي‪.‬اهــ‪ .‬كمــا‬\n‫أضــاف املدعــى عليــه الثانــي ‪ .....‬قائالً‪:‬مــا ذكــره املدعــي العــام مــن‬\n\n\n                                                                                      ‫‪20‬‬\n\f     ‫كونــي تفاوضــت مــع املصــدر علــى بيــع كميــة مــن نبــات املاريجوانــا‬\n     ‫مببلــغ قــدره مائــة ريــال وأن هنــاك كميــة مــن نبــات املاريجوانــا كانــت‬\n     ‫موجــودة يف منزلــي وأننــي اعترفــت أمــام الفرقــة القابضــة مــن أننــي قمت‬\n     ‫بتهريــب كميــة مــن نبــات املاريجوانــا مــن بنجالديــش إلــى الســعودية‬\n     ‫فهــذا صحيــح أمــا مــا ذكــره مــن كــون الكميــة املقبوضــة يف منزلــي‬\n     ‫تــزن ثالثمائــة وواحــد وثالثــن جرام ـ ًا وســتة مــن العشــرة مــن اجلــرام‬\n     ‫فهــذا ال أعلــم عنــه لكونــي ال أعــرف أوزان تلــك الكميــة ولكــن مــا مت‬\n     ‫ضبطــه مــن قبــل املكافحــة هــو الــذي كنــت أحــوزه يف منزلــي بقصــد‬\n                                                             ‫االجتــار علم ـ ًا أن اعتــرايف‬\n     ‫ا اتصــل بــي وطلــب منــي احلضــور‬    ‫وأمــا املدعــى عليــه ‪...........‬فأجــاب قائـ ً‬\n     ‫فحضــرت إلــى مســكنه يف حي‪.........‬بالدمــام ففوجئــت بالقبــض علــي‬\n     ‫مــن الفرقــة القابضــة وحاولــت الهــرب خوف ـ ًا منهــم إذ قبــل ســاعة أو‬\n     ‫ســاعتني تهجــم شــخص علــى أخــي وأخــذ منــه ألفــي ريــال غصبـ ًا عنــه وال‬\n     ‫صحــة ملــا ذكــره املدعــي العــام مــن تنســيقي مــع ‪.........‬لتهريــب احلشــيش‬\n     ‫املخــدر وأمــا أوراق القمــار فليســت عائــدة لــي وهــي عائــدة لشــخص آخــر‬\n     ‫يســكن معــي وأنــا أتعاطــى نبــات املــروان احملظــور املخــدرة وأمــا اجلــوال‬\n     ‫‪ ...........‬ويحمــل الشــريحة رقــم ‪.........‬فعائــد لــي وهــو مــن نــوع ‪ ....‬ورقــم‬\n     ‫الهاتــف اجلــوال ‪ ...........‬هكــذا اجــاب وإلحضــار الفرقــة القابضــة علــى‬\n     ‫املدعــى عليهمــا رفعــت اجللســة ويف جلســة أخــرى حضــر املدعــي العــام‬\n     ‫‪...........‬ومليحضــر الســجينان كل مــن ‪...........‬و ‪...........‬بنجالديشــيي‬\n     ‫اجلنســية ولــم يحضــر املترجمــن وال املزكيــن لهمــا وحضــرت الفرقــة‬\n     ‫القابضــة ويف جلســة أخــرى حضراملدعــي العــام ‪...........‬ولــم يحضــر كل‬\n     ‫مــن الســجينني ‪......................‬بنجالديشــيي اجلنســية ولــم يحضــر املترجم‬\n\n\n‫‪21‬‬\n\f‫بلغتهمــا وال املزكيــن لهمــا وحضــرت الفرقــة القابضــة وهــم كل مــن‬\n‫‪...........‬سجل مدني ‪ ...........‬و ‪...........‬سجل مدني ‪ ...........‬و ‪...........‬سجل‬\n‫مدنــي ‪ ...........‬و ‪...........‬ســجل مدنــي رقــم ‪...........‬وباستشــهاد الشــهود‬\n‫شــهدوا قائلــن نشــهد بــأن جميــع مــا ورد يف محضــر القبــض والتفتيــش‬\n‫أنه صحيح وقد ‪...........‬كل من ‪...........‬و ‪...........‬وبعد تعريفهم بالشهود‬\n‫قــررا قائلــن نشــهد انهــم عــدول ثقــات ورفعــت اجللســة لإلطــاع علــى‬\n‫اعتــراف املدعــى عليهمــا ويف جلســة أخــرى حضــر الســجينان ‪...........‬‬\n‫املثبــت يف اجللســات الســابقة صفتهمــا وحضــر كل مــن املترجــم املوظــف‬\n‫باحملكمــة ‪...........‬باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n‫الدمــام برقــم ‪ ...........‬يف ‪1431 /05 /12‬ه ـ واملترجــم املتعــاون ‪...........‬‬\n‫بنجالديشــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن الدمــام برقــم‬\n‫‪ ...........‬وزكاهمــا بعــد التعريــف بهمــا ‪ ...........‬هنــدي اجلنســية بنوجــب‬\n‫اإلقامــة الصــادرة مــن الدمــام برقــم ‪ ...........‬بقولــه أشــهد أن ‪ ...........‬و‬\n‫‪...........‬ثقتــان ويف هــذه اجللســة مت قــراءة شــهادة شــهود الفرقــة القابضــة‬\n‫املدونــة يف اجللســة الســابقة علــى املدعــى عليهمــا كل واحــد منهمــا علــى‬\n‫انفــراد فأجــاب ‪...........‬بقولــه كل ماجــاء يف شــهادة الفرقــة القابضــة‬\n‫مــن إعتــرايف أمامهــم فهــو صحيــح لكنــي لــم أعتــرف بهــذا اإلعتــراف‬\n‫إال بتلقــن وإكــراه منهــم هكــذا قــرر ‪.........‬وأمــا املدعــى عليــه ‪...........‬‬\n‫فأجــاب بــان واقعــة القبــض علــي صحيحــه ولكــن ال صحــة ملــا ســوى‬\n‫ذلــك مــن اعتــراف علــي باننــي انســق معــه باننــي احضــر املاريجوانــا‬\n‫املخــدر مــن بنجالديــش أوإننــي اســتقبله يف املطــار عنــد قدومــه مــن‬\n‫بنجالديــش ورفعــت اجللســة لالطــاع علــى اعتــرايف املدعــى عليهمــا‬\n‫ويف جلســة أخــرى لــدي أنــا ‪...........‬فتحــت اجللســة مبشــاركة صاحبــي‬\n\n\n                                                                                       ‫‪22‬‬\n\f     ‫الفضيلــة القاضيــن بهــذه احملكمــة الشــيخ ‪......................‬وبهــا حضــر‬\n     ‫املدعــي العــام واملدعــى عليهمــا وجــرى تــاوة مــا ُســبق ضبطــه فصادقــوا‬\n     ‫عليه‪.‬اهــ‪ .‬وأضــاف املدعــى عليــه األول ‪...........‬قائالً‪:‬مــا ذكــره املدعــي‬\n     ‫العــام يف دعــواه كلــه غيــر صحيــح عــدا أننــي أتيــت إلــى شــقته فأنــا لــم‬\n     ‫أقــم بالتنســيق مــع املدعــى عليــه الثانــي مــن أجــل تهريــب كميــة مــن‬\n     ‫بنجالديــش إلــى الســعودية وملأقــم باإلتفــاق معــه أيضـ ًا علــى بيــع كميــة‬\n     ‫مــن نبــات املاريجوانــا والــذي حصــل أن املدعــى عليــه الثانــي اتصــل بــي‬\n     ‫وطلــب منــي القــدوم إلــى شــقته فأخبرتــه أنــي قريــب منهــا بعدهــا مت‬\n     ‫القبــض علــي وأنــا أســتخدم نبــات املاريجوانــا منــذ ثــاث ســنوات ولــم‬\n     ‫يصــدر علــي حكــم بذلك‪.‬هــذا مــاأردت إضافتــه يف جوابي‪.‬اهــ‪ .‬كمــا‬\n     ‫أضــاف املدعــى عليــه الثانــي ‪.........‬قائالً‪:‬مــا ذكــره املدعــي العــام مــن‬\n     ‫كونــي تفاوضــت مــع املصــدر علــى بيــع كميــة مــن نبــات املاريجوانــا‬\n     ‫مببلــغ قــدره مائــة ريــال وأن هنــاك كميــة مــن نبــات املاريجوانــا كانــت‬\n     ‫موجــودة يف منزلــي وأننــي اعترفــت أمــام الفرقــة القابضــة مــن أننــي قمت‬\n     ‫بتهريــب كميــة مــن نبــات املاريجوانــا مــن بنجالديــش إلــى الســعودية‬\n     ‫فهــذا صحيــح أمــا مــا ذكــره مــن كــون الكميــة املقبوضــة يف منزلــي‬\n     ‫تــزن ثالثمائــة وواحــد وثالثــن جرام ـ ًا وســتة مــن العشــرة مــن اجلــرام‬\n     ‫فهــذا ال أعلــم عنــه لكونــي ال أعــرف أوزان تلــك الكميــة ولكــن مــا مت‬\n     ‫ضبطــه مــن قبــل املكافحــة هــو الــذي كنــت أحــوزه يف منزلــي بقصــد‬\n                                                           ‫االجتــار علم ـ ًا أن اعتــرايف‬\n     ‫إلــى مقــر ســكنه يف ‪.........‬وبعــد ذلــك تقاســموا الكميــة بينهمــا‬\n     ‫بالنصــف وأقــر أنــه يقــوم بترويجنبــات املاريجوانــا املخــدرة بقصــد‬\n     ‫اإلجتــار وقــد اســتعد املتهــم (‪ )...........‬للشــراء مــن املتهــم () مببلــغ (‪)100‬‬\n\n\n‫‪23‬‬\n\f‫مائــة ريــال ومتكــن املتهــم (‪ )...........‬مــن االتصــال علــى جــوال‪................‬‬\n‫الــذي يحمــل الرقــم (‪ )...........‬وكان ذلــك علــى مســمع مــن أفــراد‬\n‫الفرقــة وطلبمــن املتهــم (‪ )...........‬نبــات املاريجوانــا املخــدرة وســأل املتهــم‬\n‫(‪ )...........‬املتهــم () عــن الكميــة التــي لديــه وأخبــر (‪ )...........‬بأنهــا قــد‬\n‫نفــذت كلهــا وقــال املتهــم (‪ )...........‬للمتهــم () ســوف أحضــر لــك عنــد‬\n‫ســكنك وأعطيــك ماطلبــت ‪ ،‬ومت تكليــف أحــد أفرادالفرقــة مبرافقــة‬\n‫املتهــم (‪ ).........‬أثنــاء عمليــة الشــراء وعنــد الوصــول الــى ســكن (‪)....‬‬\n‫كان املتهــم (‪ )...........‬وأشــار لــه املتهــم (‪ ) ...........‬وخوفـ ًا مــن انكشــاف‬\n‫الفرقــة جــرى التأكــد مــن هويــة املتهــم (‪ )...........‬وقــد ظهــر عليــه اخلــوف‬\n‫وااالرتبــاك وعنــد التأكــد مــن هويتــه قــام بالهــرب ومت القبــض عليــه‬\n‫وقــد قــام مبقاومــة الفرقــة مقاومــة شــديدة عندالقبــض عليــه وقــد نتــج‬\n‫عــن ذلــك إصابــات وجــروح ســطحية ببعــض أفــراد الفرقــة‪ .‬وبتفتيــش‬\n‫الغرفــة التــي ســكن بهــا يف ‪.........‬عثــر بهــا علــى أوراق كثيــرة عليهــا‬\n‫رســوم وطالســم تســتخدم يف لعــب القمــار ‪ ،‬وكذلــك عثــر علــى حــوالت‬\n‫بنكيــة مببلــغ خمســة عشــر الفريــال (‪ )15000‬ريــال وحوالــة مببلــغ‬\n‫(‪ )5000‬خمســة االف ريــال ‪ ،‬وقــد إعتــرف إلفــراد الفرقــة مبــا نســب‬\n‫إليــه مــن قيامــه بعمليــة الترويــج املــواد املخــدرة كمــا أنــه مت القبــض‬\n‫علــى بعــض االشــخاص يف قضيــة حيــازة املاريجوانــا وأفــاد بأنهــم‬\n‫حصلــوا عليهــا مــن املتهمــن املذكوريــن وقــد أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي رقــم (‪ ).........‬وتاريــخ ‪1431/6/25‬ه ـ إيجابيــة جميــع عينــات‬\n‫ماضبــط مــن نبــات أخضــر ملــادة (املاريجوانــا) املخــدرة املدرجــة‬\n‫فياجلــدول( ‪ ) 2‬فئــة ( ب ) مــن نظــام مكافحــة املخــدرات وباستشــهاد‬\n‫الشــهود شــهدوا قائلــن نشــهد بــأن جميــع مــا ورد يف محضــر القبــض‬\n\n\n                                                                                           ‫‪24‬‬\n\f     ‫والتفتيــش أنــه صحيــح وأنــه بعــد توفــر معلومــات منأحــد املصــادر‬\n     ‫الســرية يفيــد بقيــام املتهــم ‪.........‬بتهريــب واســتخدام نبــات املاريجوانــا‬\n     ‫املخــدر فقــد اســتعد املصــدر بالتعــاون وذلــك بالشــراء منــه ومت تســليم‬\n     ‫املصــدر مائــة ريــال مبلــغ حكومــي واتصــل املصــدر علــى املتهــم وطلــب‬\n     ‫منــه نبــات املاريجوانــا املخــدر فوافــق علــى ذلــك وطلــب املصــدر احلضــور‬\n     ‫ومت تفتيــش املصــدر تفتيش ـ ًا دقيقــا وبعــد االنتقــال إلــى ســكن املتهــم‬\n     ‫حــاول املتهــم ‪ ...........‬الهــروب ومت القبــض عليــه وبتفتيــش غرفتــه وجدنــا‬\n     ‫يف غرفتــه شــنطة مفتاحهــا معــه ووجدنــا فيهــا املاريجوانــا وكرتــون‬\n     ‫مالبــس داخليــة مغلقــه باحــكام وفتحنــاه ووجدنــا فيــه كيــس آخــر‬\n     ‫معبــأ باملاريجوانــا وقصاصــت ورقيــة الواحــدة مبائــة أو مائتــي ريــال‬\n     ‫وبعــد ســؤاله عنهــا أجــاب أننــي احضرهــا مــن بنجالديــش عــن طريــق‬\n     ‫زميــل ‪ ...........‬واتصــل هاتفيـ ًا مبســمع منــا يطلــب املاريجوانــا مبائــة ريــال‬\n     ‫فقــال ‪...........‬الكميــة التــي عنــدك قــال خلصــت فقــال ســأحضر عنــدك‬\n     ‫فلمــا جئنــا عنــد بيــت ‪...........‬وجدنــا ‪ ...........‬عنــد البــاب وعنــد القبــض‬\n     ‫عليــه هــرب و بتفتيشــه وجدنــا معــه مشــد ملتصــق برجلــه غالبــا يوضــع‬\n     ‫ليمســك املهــرب مــن املخــدرات لكــن لــم جنــد داخلــه شــيئا واعتــرف‬\n     ‫امامنــا انــه ‪.........‬يســتقبل ‪...........‬يف املطــار عنــد قدومــه مــن بنجــادش‬\n     ‫هكــذا شــهدوا وقــد زكــى الشــهود كل مــن ‪ ................‬وبعــد تعريفهــم‬\n     ‫بالشــهود قــررا قائلــن نشــهد انهــم عــدول ثقــات ورفعــت اجللســة لإلطــاع‬\n     ‫علــى اعتــراف املدعــى عليهمــا ويف جلســة أخــرى حضــر الســجينان‬\n     ‫‪...........‬و ‪...........‬املثبــت يف اجللســات الســابقة صفتهمــا وحضــر كل‬\n     ‫مــن املترجــم املوظــف باحملكمــة ‪...........‬باكســتاني اجلنســية مبوجــب‬\n     ‫اإلقامــة الصــادرة مــن الدمــام برقــم ‪ ...........‬يف ‪1431 /05 /12‬ه ـ‬\n\n\n‫‪25‬‬\n\f‫واملترجــم املتعــاون بنجالديشــي اجلنســية مبوجــب اإلقامــة الصــادرة‬\n‫مــن الدمــام برقــم وتنتهــي بتاريــخ ‪1432 /11 /27‬ه ـ وزكاهمــا بعــد‬\n‫التعريــف بهمــا ‪ ................‬هنــدي اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n‫الدمــام برقــم ‪.........‬وتنتهــي بتاريــخ ‪1433 /06 /20‬ه ـ بقولــه أشــهد أن‬\n‫‪................‬و ‪................‬عــدالن ثقتــان ويف هــذه اجللســة مت قــراءة شــهادة‬\n‫شــهود الفرقــة القابضــة املدونــة يف اجللســة الســابقة علــى املدعــى عليهمــا‬\n                           ‫كل واحــد منهمــا علــى انفــراد فأجــاب ‪ ....‬بقولــه‬\n‫كمــا جــرى االطــاع علــى محضــر االســتجواب مــع املدعــى عليــه األول‬\n‫‪ ................‬املرفــق بالعاملــة لفــة رقــم (‪ )1‬صحيفــة (‪ )4‬وقــد تضمــن مــا‬\n‫نصــه‪ « :‬س‪ :‬كيــف مت القبــض عليــك؟ ج‪ :‬عندمــا اتصــل علـ َّـي املدعــو‬\n‫‪.........‬وطلــب منــي املاريجوانــا محظــورة وكنــت موجــود بالقــرب مــن‬\n‫شــقته عندهــا مت القبــض علـ َّـي مــن قبــل رجــال املكافحــة بعــد مقاومــة‬\n‫لهــم محاولــة منــي بالهــرب‪ .‬س‪ :‬عنــد التحقيــق مــع املدعــو ‪.........‬ذكــر‬\n‫بأنــه قــام بتهريــب حوالــي نصــف كيلــو مــن املاريجوانــا لصاحلــك بعــد‬\n‫التنســيق معــك بدولــة بنجالديــش وإعطائــه تلــك الكميــة مــن شــخص‬\n‫يعرفــك بعــد مكاملتــك ؟ ج‪ :‬هــذا الــكالم غيــر صحيح‪.‬اهــ‪ .‬وبعرضــه‬\n‫عليــه قــال‪ :‬لقــد بصمــت علــى هــذه األجوبــة وكلهــا صحيــح عــدا أن‬\n‫‪.........‬اتصــل بــي وطلــب منــي املاريجوانــا فهــذا غيــر صحيــح وقــد بصمــت‬\n‫دون أن أعلــم مضمــون اجلواب‪.‬أهــ‪ .‬بعدهــا جــرى االطــاع علــى احملضــر‬\n‫املعــد مــن قبــل مكافحــة املخــدرات املرفــق باملعاملــة لفــة رقــم (‪)2‬‬\n‫صحيفــة (‪ )5‬وقــد تضمــن أن أفــراد الفرقــة طلبوا إثبات املدعى عليه ‪.....‬‬\n‫فالحظــوا عالمــات االرتبــاك‪ .‬فقــال لــه أحداألعضــاء‪ :‬هــل أنــت ‪..........‬‬\n‫فقــال ال وأشــار إلــى شــخص بنجالديشــي آخــر كان يقــف يف الشــارع‪،‬‬\n\n\n                                                                                          ‫‪26‬‬\n\f     ‫وعنــد إخراجــه إثبــات هويتــه الذ بالفــرار علــى قدميــه ومت اللحــاق بــه‬\n     ‫وعنــد اإلمســاك بــه قــام مبقاومــة شــديدة وعنيفــة ممــا نتــج عنــه رضــوض‬\n     ‫وجــروح ســطحية لبعــض أفــراد الفرقــة القابضة‪.‬اهــ‪ .‬وبعرضــه عليــه‬\n     ‫قال‪:‬مــا تضمنــه هــذا احملضــر مــن هروبــي فهــذا صحيــح خلــويف منهــم‬\n     ‫أمــا ماتضمنــه مــن إنــكاري أن اســمي ‪.........‬وكذلــك مقاومتــي العنيفــة‬\n     ‫ـدي زيــادة بينــة‬\n                      ‫فهــذا غيــر صحيــح ا‪.‬هــ‪ .‬ثــم قــال املدعــي العــام ليــس لـ َّ‬\n     ‫ســوى مــا ذكرت‪.‬اهــ‪ .‬بعدهــا جــرى االطــاع علــى التقريــر الكيميائــي‬\n     ‫الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم رقــم ‪.........‬‬\n     ‫يف ‪1431/6/25‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪ )39‬املتضمــن إيجابيــة‬\n     ‫العينــة ملــادة املاريجوانــا وهــي مــن احلشــيش املخدر‪.‬اهــ‪ .‬بعدهــا تقــرر‬\n     ‫رفــع اجللســة للتأمــل ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n     ‫عليهمــا ويف هــذه اجللســة قــال املدعــى عليــه الثانــي ‪:................‬أوراق‬\n     ‫القمــار التــي مت احلصــول عليهــا مــن قبــل الفرقــة القابضــة ال تعــود لــي‬\n     ‫إمنــا وجــدت يف دورة امليــاه املشــتركة بينــي وبــن أنــاس آخريــن وأنــا‬\n     ‫ـاء علــى مــا تقـ َّـدم مــن دعــوى املدعــي‬\n                                               ‫أســتخدم نبــات املاريجوانا‪.‬أهــ‪ .‬فبنـ ً‬\n     ‫العــام املتضمنــة قيــام املدعــى عليــه األول بتلقــي نبــات املاريجوانــا املهربــة‬\n     ‫بقصــد الترويــج وتعاطيــه لنبــات املاريجوانــا وهروبــه مــن رجــال األمــن‬\n     ‫وحيــازة أوراق للعــب القمــار وقيــام املدعــى عليــه الثانــي بتهريــب مــا وزنــه‬\n     ‫ثالثمائــة وواحــد وثالثــون جرامـ ًا وســتة مــن العشــرة مــن اجلــرام مــن نبــات‬\n     ‫املاريجوانــا واشــتراك املدعــى عليهمــا األول والثانــي يف حيــازة مــا وزنــه‬\n     ‫ثالثمائــة وواحــد وثالثــون جرامـ ًا وســتة مــن العشــرة مــن اجلــرام مــن نبــات‬\n     ‫املاريجوانــا بقصــد التعاطــي واالجتــار وحيــازة كل واحــدٍ منهمــا ألوراق‬\n     ‫تســتخدم للعــب القمــار وتعاطــي كل واحــد منهمــا لنبــات املاريجوانــا‬\n\n\n‫‪27‬‬\n\f‫وجــواب املدعــى عليــه األول ‪................‬املتضمــن إنــكار جميــع مــا جــاء‬\n‫ا عــدا تعاطيــه لنبــات املاريجوانــا وهروبــه‬            ‫يف الدعــوى جملــة وتفصي ـ ً‬\n‫مــن رجــال األمــن وجــواب املدعــى عليــه الثانــي ‪................‬املتضمــن‬\n‫مصادقتــه علــى بعــض مــا جــاء يف الدعــوى مــن ترويجــه للكميــة مــن‬\n‫نبــات املاريجوانــا وكــذا حيازتــه للكميــة األخــرى وتعاطيــه لنبــات‬\n‫املاريجوانــا وإنــكار قيامــه بتهريــب كميــة مــن نبــات املاريجوانــا مــن‬\n‫أن املدعــي العام‬    ‫بنجالديــش إلــى الســعودية وحيازتــه ألوراق القمــار ومبــا َّ‬\n‫لــم يقــدم بينــة موصلــة ملــا ادعــى بــه علــى املدعــى عليــه األول ولكــن ثمــة‬\n‫قرائــن تتجــه عليــه وهــي اآلتــي‪:‬أوالً‪ /‬إقــراره يف محضــر االســتجواب أنــه‬\n‫مت القبــض عليــه بعدمــا اتصــل عليــه املدعــو ‪.........‬وطلــب منــه املاريجوانــا‬\n‫محظورة‪.‬ثاني ـاً‪ /‬هروبــه مــن رجــال القبــض بعدمــا طلبــوا إثبــات هويتــه‪.‬‬\n‫ثالث ـاً‪ /‬ظهــور عالمــات االرتبــاك عليــه ســاعة القبــض عليــه‪ .‬رابع ـاً‪/‬‬\n‫أن املدعــى عليــه األول قــدم إلــى محــل ســكن املدعــى عليــه الثانــي‬\n‫بعــد اتصالــه عليــه مباشــرة وقــد ذكــر أثنــاء املهاتفــة أنــه قريــب منــه‪.‬‬\n‫خامسـاً‪ /‬إقــرار املدعــى عليــه الثانــي ‪.........‬باشــتراك املدعــى عليــه األول‬\n‫‪ ................‬معــه يف تهريــب وترويــج الكميــة املذكــورة‪ .‬وهذااإلقــرار‬\n‫كان حجــة قاصــرة إال أنــه يعتبــر مقويـ ًا للقرائــن امل ـ ُ َـشار إليهــا وتلــك‬‫َ‬     ‫وإن‬\n                ‫بتوجــه التهمــة عليــه‪.‬‬\n                                       ‫القرائــن باجتماعهــا وتظافرهــا توحــي ُّ‬\n‫أمــا املدعــى عليــه الثانــي ‪ ................‬فقــد قَ ـ َّـدم املدعــي العــام بينــة علــى‬\n‫دعــواه يف تهريــب الكميــة املذكــورة وهــي إقــراره املصــدق شــرع ًا ومــا‬\n‫دفــع بــه مــن كونــه أراد التخلــص مــن القضيــة فهــذا غير معتدٍ بــه ويعتبر‬\n‫رجوعـ ًا عــن اإلقــرار ومبــا أنــه قــد أقـ ّـر إقــرار ًا مصدقـ ًا شــرع ًا بأنــه قــام‬\n‫ـرار طواعِ َي ٍة‬\n            ‫بالتهريــب ملــادة احلشــيش املخــدر‪ ،‬وقــد جــاء يف إقــراره أنه إقـ ُ‬\n\n                                                                                                 ‫‪28‬‬\n\f     ‫مــن غيــر إكــرا ٍه أو إجبــا ٍر مــن أحــدٍ واإلقــرار مــن أقــوى طــرق اإلثبــات‪،‬‬\n                                   ‫وقــد قـ َّـرر أهــل العلــم َأ َّن حقــوق اهلل تعالــى التــي ال ُتـ َ‬\n          ‫ـدرأ بالشــب َه ِة ال ُي َ‬\n      ‫قبــلُ‬\n     ‫درأ‬ ‫فيهــا الرجــوع عــن اإلقــرار بال خِ الف‪ ،‬والتعازيـ ُـر من احلقوق التي ال ُت َ‬\n     ‫قبــل فيــه الرجــوع عــن اإلقرار‪(.‬املغنــي ‪ ،95/5‬حاشــية ابــن‬               ‫بالشــب َه ِة فــا ُي َ‬\n     ‫أن املدعــي العــام لــم يقــدم بينــة على حيــازة املدعى‬        ‫عابديــن ‪ .)60/4‬ومبــا َّ‬\n     ‫أن نبــات املاريجوانــا‬     ‫عليهمــا لــأوراق التــي تســتخدم للعــب القمــار ومبــا َّ‬\n     ‫مــن أنــواع احلشــيش املخــدرة فترويجــه وتهريبــه وحيازتــه مــن اإلفســاد‬\n     ‫ـعي لنشــر‬ ‫يف األرض وهــو مــن الذنــوب الع َِظــام واآلثــام ا ِجلســام‪ ،‬وهــو سـ ٌ‬\n     ‫الرذيلــة والفســاد بــن النــاس‪ ،‬وقــد قــال تعالــى ( إن اهلل اليصلــح عمــل‬\n     ‫املفســدين ) وقــال جــل جاللــه ( وال تفســدوا يف األرض بعــد إصالحهــا‬\n     ‫ـاء الشــرع‬  ‫) فضــرر احلشــيش عظيـ ٌـم علــى الضــرورات اخلمــس التــي جـ َ‬\n     ‫بحفظهــا وصيانتهــا وهــي موجبـ ٌة لســخط اهلل وغضبــه وهــذا يســتدعي‬\n     ‫ـاء علــى ماتضمنتــه املــواد‬          ‫تشــديد التعزيــر علــى املدعــى عليهمــا؛ وبنـ ً‬\n     ‫(‪ )37،52،56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لذلــك‬\n     ‫كلــه فقــد قررنــا اآلتــي‪:‬أوالً‪ /‬رددنــا دعــوى املدعــى العــام ضــد املدعــى‬\n     ‫عليــه األول ‪................‬يف االشــتراك مــع املدعــى عليــه الثانــي يف تهريــب‬\n     ‫الكميــة املذكــورة مــن نبــات املاريجوانــا واالشــتراك معــه أيض ـ ًا يف‬\n     ‫حيــازة مــا وزنــه ثالثمائــة وواحــد وثالثــون جرامـ ًا وســتة مــن العشــرة مــن‬\n     ‫اجلــرام مــن نبــات املاريجوانــا بقصــد التعاطــي واالجتــار ومقاومــة الفرقــة‬\n     ‫القابضــة وتتوجــه عليــه التهمــة يف ذلــك‪ .‬ثانيـاً‪ /‬ثبــت لدينــا إدانــة املدعــى‬\n       ‫عليــه األول ‪................‬واملدعــى عليــه الثانــي ‪................‬بتناول كل واحدٍ‬\n     ‫منهمــا نبــات املاريجوانــا املخــدر‪ .‬ثالث ـاً‪ /‬ثبــت لدينــا إدانــة املدعــى عليــه‬\n     ‫الثانــي ‪................‬بتهريــب مــا وزنــه نصــف كيلــو مــن نبــات املاريجوانــا‬\n\n\n‫‪29‬‬\n\f‫مــن بنجالديــش إلــى داخــل الســعودية كمــا ثبــت لدينــا إدانتــه بحيــازة مــا‬\n‫وزنــه ثالثمائــة وواحــد وثالثــون جرامـ ًا وســتة مــن العشــرة مــن اجلــرام مــن‬\n‫نبــات املاريجوانــا بقصــد االجتــار والتعاطــي‪ .‬رابعـاً‪ /‬رددنــا دعوى املدعي‬\n‫العــام يف حيــازة املدعــى عليهمــا ألوراق تســتخدم للعــب القمــار‪ .‬خامسـاً‪/‬‬\n‫قررنــا تعزيــر املدعــى عليــه األول ‪................‬بالســجن ملــدة خمــس ســنوات‬\n‫وجلــده خمســمائة جلــدة وتعزيــر املدعــى عليه الثاني ‪ ................‬بالســجن‬\n‫ملــدة عشــر ســنوات وجلــده ســبعمائة جلــدة علــى أن تبــدأ فترة الســجن من‬\n‫تاريــخ القبــض علــى كل واحــدٍ منهمــا ويكــون جلــد كل واحــد منهمــا‬\n‫مفرقـ ًا علــى دفعــات متســاوية كل دفعــة خمســون جلــدة وبــن كل دفعة‬\n‫عشــرة أيــام علــى أن تنفــذ أربــع دفعــات مــن دفعــات اجللــد أمــام جامــع‬\n‫خــادم احلرمــن الشــريفني بالدمــام‪ .‬سادسـاً‪ /‬إقامةحــد شــرب املســكر‬\n‫علــى كل واحــد مــن املدعــى عليهمــا بجلــده ثمانــن جلــدة دفعــة واحــدة‪.‬‬\n‫ســابعاً‪ /‬تغــرمي املدعــى عليــه الثانــي مائــة ألــف ريــال تــؤول خلزينــة الدولــة‬\n‫العامــة‪ .‬ثامنـاً‪ /‬إبعــاد املدعــى عليهمــا جميعـ ًا مــن البــاد بعــد اســتيفاء مــا‬\n‫ـاء للعبــاد والبــاد مــن شــرهما‪ .‬تاســعاً‪/‬‬  ‫لهمــا وماعليهمــا مــن حقــوق اتقـ ً‬\n‫رددنــا دعــوى املدعــي العــام يف مصــادرة اجلــوال العائــد للمدعــى عليــه‬\n‫األول والــذي يحمــل الشــريحة رقــم ‪ .....‬عاشــراً‪ /‬قررنــا مصــادرة اجلــوال‬\n‫العائــد للمدعــى عليــه الثانــي ‪.........‬والــذي يحمــل الشــريحة رقــم ‪......‬‬\n‫وعــدم صــرف الشــريحة لــه مــرة أخــرى‪ .‬وبذلــك كلــه حكمنــا وبعــرض‬\n‫احلكــم علــى املدعــي العــام قــرر عــدم القناعــة وطلــب رفــع املعاملــة إلــى‬\n‫محكمــة االســتئناف بالئحــة اعتراضيــة كمــا قــرر كل واحــدٍ مــن‬\n‫املدعــى عليهمــا قناعتهمــا باحلكــم وقــد قــام بــدور الترجمــة املتعــاون‬\n‫مــع احملكمــة ‪................‬املــدون هويتــه ســابق ًا وكانــت ســاعة النطــق‬\n\n\n                                                                                          ‫‪30‬‬\n\f     ‫باحلكــم متــام الســاعة احلاديــة عشــرة والنصفوبــاهلل التوفيــق وصلــى اهلل‬\n       ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‪ .‬حــرر يف ‪1433/4/12‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ففــي متــام‬\n     ‫ـاء علــى ورود‬   ‫الســاعة احلاديــة عشــرة مــن يــوم االثنــن ‪1434/3/16‬ه ـ بنـ ً‬\n     ‫املعاملــة مــن محكمــة االســتئناف برقــم ‪................‬يف ‪1434/1/25‬ه ـ‬\n     ‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة اســتئناف الدائــرة اجلزائيــة‬\n     ‫اخلماســية األولــى رقــم ‪ ................‬يف ‪1434/1/6‬ه ـ وقــد تضمــن مــا‬\n     ‫نصــه‪ « :‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n     ‫املعاملــة لوحــظ أن القــرار لــم يــرد فيــه مطالبــة املدعــي العــام ملالحظــة‬\n     ‫مــا ذكــر وإكمــال الــازم‪ .‬توقيــع وختــم أصحــاب الفضيلــة كل مــن‪:‬‬\n     ‫د‪« ................ ................./‬ا‪.‬هــ‪ .‬واجلــواب علــى ذلــك أنــه لــم يتــم إضافــة‬\n     ‫طلبــات املدعــي العــام ســهواً‪ .‬وباالطــاع علــى ضبــط القضيــة وجدنــا أن‬\n     ‫طلباتــه مــا نصــه‪« :‬وحيــث إن مــا أقــدم عليه املتهمان املذكــوران ‪ -‬وهما‬\n     ‫بكامــل أهليتهمــا املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫ونظامـ ًا ‪ ،‬أطلــب اآلتــي‪ -:‬أو ًال ‪ :‬إثبــات إدانتهمــا مبــا أســند إليهمــا وفقـ ًا‬\n     ‫للفقــرة (‪ )2‬مناملــادة (‪ )3‬واملــادة رقــم (‪ )64‬مــن نظام مكافحة املخدرات‬\n     ‫واحلكــم عليهمــا بالقتــل تعزيــر ًا اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n     ‫(‪ )37‬مــن نظــام مكافحــة املخــدرات ‪ ،‬مــع مراعــاة املــادة (‪ )62‬مــن‬\n     ‫النظــام بشــأن العقوبــة األشــد ثانيـ ًا ‪ :‬مصــادرة اجلــوال رقــم (‪)................‬‬\n     ‫والــذي يحمــل الشــريحة رقــم (‪ ).........‬ورقــم االتصــال (‪)................‬‬\n     ‫العائــد للمتهــم (‪ ، )................‬واجلــوال رقــم (‪ )................‬والــذي يحمــل‬\n     ‫الشــريحة رقــم (‪ ).........‬ورقــم االتصــال (‪ )................‬والعائــد للمتهــم‬\n     ‫(‪ ،)................‬اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام‬\n\n\n‫‪31‬‬\n\f‫مكافحــة املخــدرات وعــدم صــرف شــريحة للمتهمــن املذكوريــن‬\n‫اســتنادا الــى تعميــم صاحــب الســمو امللكــي النائــب الثانيرائيــس‬\n‫مجلــس الــوزراء وزيــر الداخليــة رقــم(‪ )9798‬وتاريــخ ‪1428/10/9‬ه ـ‬\n‫«ا‪.‬هــ‪ .‬علمـ ًا أنــه مت عمــل مســودة لضبــط هــذه القضيــة ولــم يقــم املوظــف‬\n‫بضبطهــا يف حينــه ســهو ًا وفضيلــة القاضــي املشــارك ‪................‬يف دورة‬\n‫القضــاء التجــاري ملــدة شــهرين‪ .‬بعدهــا تقــرر رفــع اجللســة متــام الســاعة‬\n‫احلاديــة عشــرة والربــع وســيتم رفــع كافــة أوراق املعاملــة إلــى محكمــة‬\n                       ‫االســتئناف وبــاهلل التوفيــق‪ .‬حــرر يف ‪1434/3/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي متام‬\n‫الســاعة احلاديــة عشــر والربــع مــن يــوم االربعــاء ‪1434/6/21‬ه ـ فتحــت‬\n‫بناء على ورود املعاملة من محكمة االســتئناف برقم ‪................‬‬      ‫اجللســة ً‬\n‫يف ‪ 1434/5/6‬وبرفقهــا قــرار أصحــاب الفضيلــة رقــم ‪................‬يف‬\n‫‪1434/5/1‬ه ـ وقــد تضمــن املالحظــة علــى احلكــم مبــا نصــه‪ « :‬وحيــث‬\n‫ســبق دراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا أجاببــه أصحــاب الفضيلــة علــى قرارنــا رقــم‬\n‫‪ ................‬يف ‪1434/1/6‬ه ـ لوحــظ مــا يلــي‪ :‬أوالً‪ /‬أن اجللســة األخيــرة‬\n‫لــم ترفــق يف صــورة الضبــط‪ .‬ثانيـاً‪ /‬أن مــا حكــم بــه أصحــاب الفضيلــة‬\n‫علىاملدعــى عليهمــا قليــل جــد ًا خلطــورة مــا أقــدم عليــه املدعــى عليهمــا‪.‬‬\n‫توقيــع وختــم أصحــاب الفضيلــة كل مــن‪ :‬د‪.« ................ /‬اهــ‪ .‬وجوابنــا‬\n‫علــى ذلــك أمــا مــا ذكــر يف أو ًال فلــم يتم إحلاق ذلك ســهواً‪ .‬وأما املالحظة‬\n‫الثانيــة فلــم يظهــر لنــا خــاف مــا حكمنــا بــه بعدهــا تقــرر رفــع اجللســة‬\n‫متــام الســاعة احلاديــة عشــر والنصــف وســيتم رفــع كافــة أوراق املعاملــة‬\n‫حملكمــة االســتئناف حســب املتــب وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n\n\n                                                                                     ‫‪32‬‬\n\f                      ‫علــى نبينــا محمــد وآلــه وصحبــه‪ .‬حــرر يف ‪1434/6/21‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫متــام الســاعة الثانيــة عشــرة ظهــر ًا مــن يــوم االربعــاء ‪1434/8/24‬ه ـ‬\n     ‫ـاء علــى ورود املعاملــة مــن محكمــة االســتئناف‬             ‫فتحــت اجللســة بنـ ً‬\n     ‫باملنطقــة الشــرقية برقــم ‪ ................‬يف ‪1434/7/17‬ه ـ وبرفقهــا قــرار‬\n     ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة اخلماســية األولــى رقــم‬\n     ‫‪ ................‬يف ‪1434/7/10‬ه ـ وقــد تضمــن املالحظــة علــى احلكــم‬\n     ‫مبــا نصــه‪ « :‬وحيــث ســبق دراســة القــرار وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه أصحــاب‬\n     ‫الفضيلــة علــى قرارنــا رقــم ‪ ................‬يف ‪1434/1/6‬ه ـ وقرارنــا رقــم‬\n     ‫‪ ................‬يف ‪1434/5/1‬ه ـ فــإن الدائــرة تقــرر إعــادة املعاملــة ألصحاب‬\n     ‫الفضيلــة للمــرة الثانيــة إلعــادة التأمــل والنظــر فيمــا يحفــظ املجتمــع مــن‬\n     ‫كل فســاد وشــر فــإن ذلــك مطلــوب شــرعاً‪ .‬توقيــع وختــم أصحــاب‬\n     ‫الفضيلــة كل مــن‪ :‬د‪« ................/‬ا‪.‬هــ‪ .‬وجوابنــا علــى ذلــك‪ :‬أننــا نتفــق‬\n     ‫مــع أصحــاب الفضيلــة بعمــل مــا مــن شــأنه ضبــط أمــن املجتمــع فهــذا‬\n     ‫مــن أهــم مقاصــد القضــاء ولكــن اخلــاف إمنــا هــو يف حتقيــق املنــاط‬\n     ‫بكــون املدعــى عليهمــا يســتحقان زيــادة العقوبــة أم ال؛ فمــن نافلــة القول‬\n     ‫التأكيــد علــى أنــه ال يســوغ تنزيــل مقصــد أمــن املجتمــع علــى البــريء‬\n     ‫ثــم معاقبتــه اســتصحاب ًا للمقصــد املشــار إليــه؛ لــذا نأمــل مــن أصحــاب‬\n     ‫الفضيلــة تنقيــح مــا يرونــه مــن وقائــع مؤثــرة وإبــراز القرائــن التــي توجــب‬\n     ‫زيــادة تعزيرهمــا ممــا يكــون قــد خفــي علينــا ثــم تقــرر رفــع اجللســة متــام‬\n     ‫الســاعة الثانيــة عشــرة والربــع علمـ ًا أن فضيلــة الشــيخ ‪................‬يتمتــع‬\n     ‫بإجــازة اعتياديــة ولكــون رئيــس اجللســة ســيتمتع بإجــازة إلــى بعــد شــهر‬\n\n\n‫‪33‬‬\n\f‫رمضــان ونظــر ًا لكــون احلكــم باألغلبيــة وخشــية مــن تأخــر املعاملــة مت‬\n‫اجلــواب عنهــا وســيتم رفــع كافــة أوراق املعاملةإلى محكمة االســتئناف‬\n‫حســب املتبــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمدوعلــى‬\n                                ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/8/24‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبدينــة الدمــام‬\n‫برقــم ‪ ................‬وتاريــخ ‪1434/10/29‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪................‬وتاريــخ ‪1434/11/3‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫ذو الرقــم ‪ ................‬والتاريــخ ‪1433/5/10‬ه ـ الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمــة الشــيخ‪................/‬اخلاص بدعــوى‪/‬‬\n‫ـد‪/‬كل مــن ‪................-1‬بنجالديشــي اجلنســية‬   ‫ٍ‬         ‫املدعــي العــام ضـ‬\n‫‪................-2‬بنجالديشــي اجلنســية يف قضيــة مخــدرات وقــد تضمــن‬\n‫القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ .‬وحيــث‬\n‫ســبق دراســة القــرار وصــورة ضبطــه والالئحــة األعتراضيــة وأوراق‬\n‫املعاملــة وباإلطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة علــى قرارنــا‬\n‫رقــم ‪ ................‬وتاريــخ ‪1434/1/6‬ه ـ وقرارنــا رقــم ‪ ................‬وتاريــخ‬\n‫‪1434/5/1‬ه ـ وقرارنــا رقــم ‪ ................‬وتاريــخ ‪1434/7/10‬ه ـ قررنــا‬\n‫املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‪.‬واهلل املوفــق وصلىــاهلل‬\n‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪ 1434/11/11‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                        ‫‪34‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":12,"source_page_end":34,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e8b41194366881e008febfb6854a2f2efe5fc968eb5544bbdc30669aa80ea684","normalized_text_hash":"d37821a7a270e7fb14d07c89d95026d4da3ed256c82bf285a433a5fe4973c17a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p12-33237852"},{"id":"b03831bd-75f0-5f4e-89df-5ef52df1e799","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب الهيروين -كبسوالت داخل االحشاء -إقرار حتقيقا -ثبوت إدانة املدعى عليه -التعزير بالسجن","document_number":"33345920","case_number":"3316760","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض حضر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/16","year":"1434","subject":"مخدرات -تهريب الهيروين -كبسوالت داخل االحشاء -إقرار حتقيقا -ثبوت إدانة املدعى عليه -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 33345920 :‬تاريخه‪1434/7/16 :‬هـ‬\n                         ‫رقم الدعوى‪3316760 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3462440‬تاريخه‪1434/3/15 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬تهريــب الهيرويــن ‪ -‬كبســوالت داخــل االحشــاء ‪ -‬إقــرار‬\n     ‫حتقيقــا ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬التعزيــر بالســجن‬\n                                                              ‫ً‬     ‫املدعــى عليــه‬\n            ‫واجللــد والغرامــة ومصــادرة اجلــوال واملبلــغ املضبــوط بحوزتــه‪.‬‬\n\n\n\n\n     ‫‪ -‬قــول الرســول صلــى اهلل عليــه وســلم‪ :‬فــإن وجــدمت للمســلم مخرجــا‬\n     ‫فخلــوا ســبيله فــإن اإلمــام ألن يخطــئ يف العفــو خيــر لــه مــن أن يخطــئ‬\n                                                                           ‫يف العقوبــة‪.‬‬\n     ‫‪-‬الفقــرة (‪ )1‬املــادة (‪ )37‬والفقــرة (‪ )2‬املــادة (‪ )37‬والفقــرة (‪ )2‬مــن املــادة‬\n                           ‫(‪ )56‬مــن نظــام مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n     ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بجلــب وتهريــب املخــدرات ‪-‬‬\n     ‫الهيرويــن‪ -‬بقصــد الكســب املــادي‪ ،‬أقــر املدعــى عليــه بالواقعــة‪،‬‬\n     ‫مت القبــض علــى املدعــى عليــه وأثبــت التقريــر الكيميائــي الشــرعي‬\n     ‫احتــواء املــادة املضبوطــة علــى الهيرويــن‪ ،‬طلــب املدعــي العــام احلكــم‬\n     ‫علــى املدعــى عليــه بعقوبــة القتــل تعزيــر ًا ومصــادرة املبلــغ املالي املضبوط‬\n     ‫وقــدره مائــة ري ــال كونــه ناجتـ ًا مــن ارتــكاب اجلرميــة ومصــادرة اجلــوال‬\n\n\n‫‪35‬‬\n\f‫املضبــوط املســتخدم يف ارتــكاب اجلرميــة‪ ،‬حكمــت احملكمــة بثبــوت‬\n‫إدانــة املدعــى عليــه بتهــرب الهيرويــن‪ ،‬واحتياطا للدمــاء وللقرائن والتهم‬\n‫قــررت احملكمــة احلكــم علــى املدعــى عليــه بتعزيــره بالســجن خمــس‬\n‫عشــرة ســنة‪ ،‬وجلــده خمســن جلــدة تكــرر عليــه خمــس عشــرة مــرة‬\n‫بــن كل مــرة وأخــرى مــدة شــهرين‪ ،‬وغرامــة ماليــة قدرهــا مائــة ألــف‬\n‫ري ــال‪ ،‬ومصــادرة جوالــه واملبلــغ املضبــوط بحوزتــه‪ ،‬وتوصــي باإلبعــاد‬\n‫خــارج البــاد بعــد انتهــاء مالــه ومــا عليــه مــن حقــوق‪ ،‬قــرر املدعــى عليــه‬\n‫قناعتــه باحلكــم‪ ،‬مت تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ ................‬القضــاة يف احملكمــة‬\n‫العامــة بالريــاض حضــر ‪................‬وادعــى قائــا بصف ــتي مدعيــ ًا عامــ ًا‬\n‫يف دائ ــرة االدع ــاء الع ــام مبدين ــة الري ــاض أدع ــي علــى ‪21(................ /‬‬\n‫ســنة) باكســتاني اجلنســية مبوجــب جــواز الســفر رقــم(‪)................‬‬\n‫يتحــدث اللغــة البشــتو ويفهــم األوردو مســلم أوقــف بتاريــخ ‪1432/8/8‬هـ‬\n‫وأحيــل إلــى شعبةســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف‬\n‫رقــم() وتاريــخ ‪1432/8/19‬ه ـ اســتناد ًا للقــرار الــوزاري رقــم(‪)1900‬‬\n‫وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املادة رقم (‪ )112‬من نظام اإلجراءات‬\n‫اجلزائيــة حيــث إنــه بتاريــخ ‪1432/8/8‬ه ـ قبــض علــى املدعــى عليــه مــن‬\n‫قبــل جمــرك مطــار امللــك خالــد الدولــي بالريــاض إثــر قدومــه علــى‬\n‫الرحلــة رقــم (‪ )808‬القادمــة مــن مطــار كراتشــي عبــر رحلــة طيــران ‪.....‬‬\n‫حيــث مت االشــتباه بــه وبإحالتــه إلــى جهــاز األشــعة والكشــف عليــه‬\n‫ظهــرت النتيجــة بوجــود أجســام غريبــة داخــل أحشــائه فقــام بإنــزال‬\n\n                                                                                          ‫‪36‬‬\n\f     ‫(‪ )116‬مائــة وســت عشــرة كبســولة حتتــوي علــى مــادة بنيــة اللون يشــتبه‬\n     ‫أن تكون من الهيروين املخدر بلغ وزنها اإلجمالي مع األغلفة(‪)955.1‬‬\n     ‫تســعمائة وخمسةوخمســن جرام ـ ًا وعشــر اجلــرام وقــد أثبــت التقريــر‬\n     ‫الكيميائــي ال ــشرعي الصــادر مــن مركزمراقبــة الســموم والكيميــاء‬\n     ‫الطبيــة الشــرعية بالريــاض رقم(‪.........‬لعــام ‪1432‬ه ـ احتواءعينــة‬\n     ‫املســحوق الــذي بداخــل إحــدى الكبســوالت املهربــة على مــادة الهيروين‬\n     ‫وهــو مــن املــواد املخــدرة واملدرجــة باجلــدول رقــم(‪ )1‬فئــة(أ) امللحــق بنظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة وبســماع أقوالــه أقــر بتهريــب‬\n     ‫الكميــة املضبوطــة مــن الهيرويــن املخــدريف أحشــائه إليصالهــا إلــى‬\n     ‫مدينة الرياض وأنه أخذها من شــخص يف باكســتان يدعى ‪................‬‬\n     ‫وأخبــره أنــه عنــد وصولــه إلــى مدينــة الريــاض وإنزالــه الكبســوالت‬\n     ‫ســوف يعطــي أحــد أقربائــه مبلــغ مالــي قــدره(‪ )1600‬ألــف وســتمائة‬\n     ‫روبيةمقابــل كل كبســولة وباســتجوابه أقــر بصحــة الواقعــة وبتهريبــه‬\n     ‫الكميــة املضبوطــة مــن الكبســوالت يف أحشــائه إلــى اململكــة حيــث‬\n     ‫عــرض عليــه شــخص باكســتاني يدعــى ‪ ................‬ويســكن يف قريتــه‬\n     ‫مبلــغ مالــي قــدره(‪ )100.000‬مئــة ألــف روبيــة باكســتانية ومنحــه‬\n     ‫تأشــيرة عمــل يف الســعودية وتذكــرة ســفر مقابــل تهريبــه للكبســوالت‬\n     ‫عــن طريــق أحشــائه فوافــق علــى ذلــك ويف نفــس يــوم الســفر أعطــاه‬\n     ‫‪.........‬الكبســوالت وذهــب معــه إلــى أحــد األماكــن فقــام بابتــاع‬\n     ‫الكبســوالت ثــم توجــه إلــى املطــار يف كراتشــي وغــادر إلــى الســعودية‬\n     ‫وأنــه قبــض عليــه عندوصولــه مطــار امللــك خالــد الدولــي بالريــاض وأن‬\n     ‫‪.........‬طلــب منــه عنــد وصولــه أن يســتقل ســيارة أجــره ثــم يقــوم باالتصــال‬\n     ‫عليه وهو ســيخبره عن الشــخص الذي ســوف يســلمه الكبســوالت(ومت‬\n\n\n‫‪37‬‬\n\f‫مخاطبــة مكافحــة املخــدرات بشــرق الريــاض التخــاذ الــازم حيــال‬\n‫باخلطــاب رقــم(‪ ).........‬وتاريــخ ‪1432/8/26‬هــ) وأن املبلــغ املالــي‬\n‫املضبــوط معــه قــدره (‪ )100‬مائــة ريــال قــد أعطــاه إيــاه ‪................‬‬\n‫ملصاريــف الســفر وأنــه ســبق أن اتصــل علــى‪ ................‬مــن جهــاز جوالــه‬\n‫الــذي يحمــل شــريحة اتصــال باكســتانية(وجرى حجــز املبلــغ املالــي‬\n‫وجهــاز اجلــوال اســتناد ًا للفقــرة(‪ )2‬مــن املــادة(‪ )53‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة باخلطــاب رقــم (‪ ).........‬وتاريــخ‬\n‫‪1432/8/26‬ه ـ ونفــى علمــه مابداخــل الكبســوالت التــي هربهــا يف‬\n‫أحشــائه وصــادق علــى إقــراره شــرع ًا وأســفر التحقيــق عــن اتهامــه‬\n‫بتهريــب(‪ )116‬مائــة وســت عشــرة كبســولة بلــغ وزنهــا مــع‬\n‫األغلفــة(‪ )955.1‬تســعمائة وخمســة وخمســن جراماًوعشــر اجلــرام مــن‬\n‫الهيرويــن املخــدر املجــرم مبوجــب الفقــرة(‪ )1‬مــن املــادة (الثالثــة) مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا‬\n‫ضبــط املعاقــب علــى ذلــك شــرعا وفقــا لقــرار االتهــام رقــم (‪)..................‬‬\n‫لعام‪1432‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪-1:‬إقــراره املصــادق عليــه‬\n‫شــرع ًا املــدون ص(‪ )1‬بدفتــر التحقيــق املرفــق علــى اللفــة رقــم(‪)20‬‬\n‫‪-2.‬إقــراره حتقيق ـ ًا املــدون ص(‪ )3-2-1‬بدفتــر التحقيــق املرفــق علــى‬\n‫اللفــة رقــم(‪-3. )19‬اعترافــه مبحضــر ســماع أقوالــه األوليــة املــدون‬\n‫ا علــى اللفــة رقم(‪-4)11-10-9‬محضــر القبــض املرفــق علــى‬                   ‫تفصي ـ ً‬\n‫اللفــة رقــم(‪-5. )2‬التقريــر الكيميائــي الشــرعي املرفــق لفــة رقــم(‪)27‬‬\n‫وببحــث ســوابقه اتضــح عــدم وجــود ســوابق جنائيــة مســجلة عليــه حتــى‬\n‫تاريخــه وصــدر قــرار جلنــة إدارة الهيئــة رقــم(‪/2463‬ر) لعــام ‪1432‬ه ـ‬\n\n\n                                                                                         ‫‪38‬‬\n\f     ‫باملوافقــة علــى ماانتهــى إليــه قــرار االتهــام وحيــث إن مــا أقــدم عليــه‬\n     ‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا مبوجــب نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه األصليــة‬\n     ‫والتكميليــة أطلــب إثبــات إدانتــه مبــا أســند إليــه وأطلــب احلكــم عليــه‬\n     ‫باآلتــي ‪-1-:‬بعقوبــة القتــل تعزيــر ًا الــواردة يف الفقــرة(‪ )1‬مــن البنــد(أوالً)‬\n     ‫مــن املــادة(‪ )37‬مــن النظــام املشــار إليه‪-2.‬مصــادرة املبلــغ املالي املضبوط‬\n     ‫مــع املذكــور قــدره(‪ )100‬مائــة ريــال كونــه ناجتـ ًا مــن ارتــكاب اجلرميــة‬\n     ‫اســتناد ًا للفقــرة (‪ )2‬مــن املــادة (‪ )53‬مــن النظــام املشــار إليه‪-3‬مصــادرة‬\n     ‫جهــاز اجلــوال املضبــوط معــه مــن نــوع ‪ ....‬والــذي يحمــل الرقــم املصنعــي‬\n     ‫(‪ ).........‬املســتخدم يف ارتــكاب اجلرميــة اســتناد ًا للفقــرة(‪ )1‬مــن‬\n     ‫املــادة(‪ )53‬مــن النظــام املشــار إليــه ثــم حضــر ‪................‬باكســتاني‬\n     ‫اجلنســية حامــل بطاقــة نزيــل رقم‪.........‬صــادرة مــن ســجن امللــز وبســؤاله‬\n     ‫عــن دعــوى املدعــي العــام أجــاب قائالبواســطة مترجــم احملكمــة‬\n     ‫املتعــاون ‪................‬باكســتاني اجلنســية مبوجــب اإلقامة رقــم ‪................‬‬\n     ‫ماذكــره املدعــي العــام يف دعــواه غيــر صحيــح والصحيــح أننــي اشــتريت‬\n     ‫تأشــيرة عمــل يف الســعودية مــن شــخص مائــة وثمانــن ألــف روبية ودفعت‬\n     ‫لــه مائــة ألــف روبيــة وبقــي لــه ثمانــن ألــف روبيــة وقبــل ســفري علــى‬\n     ‫الطائــرة بحوالــي إثنــا عشــر ســاعة شــربت عصيــرا لــدى املدعــو‬\n     ‫‪................‬وبعدهــا فقــدت الوعــي ولــم أحــس بشــيء حتــى صعــدت‬\n     ‫الطائــرة ويف الطائــرة حسســت ألــم يف بطنــي ولــم أكتشــف مــايف بطنــي‬\n     ‫إال بعــد وصولــي إلــى الســعودية وحينهــا عرفــت أنــه مت اســتغاللي مــن‬\n     ‫قبــل عصابــة مخــدرات لتهريــب مــادة الهيرويــن املخــدر يف أحشــائي وأنــا‬\n     ‫ال أعلــم عــن ذلــك شــيئ ًا إطالقــا كمــا أبــن أن والــدي متوفــى وأنــا أعيــل‬\n\n\n‫‪39‬‬\n\f‫أســرة مكونــة مــن أم وأختــن هكــذا أجــاب وبعــرض ذلــك علــى املدعي‬\n‫العــام قــال ماذكــره املدعــى عليــه غيــر صحيــح والصحيــح مــا جــاء يف‬\n‫دعــواي وبســؤاله البينــة قــال ليــس لــدي ســوى مــا تضمنتــه أوراق املعاملــة‬\n‫ويف جلســة أخــرى حضــر الطرفــان واملترجــم ‪................‬بنجالديشــي‬\n‫اجلنســية مبوجــب اإلقامــة رقــم ‪ ................‬ثــم جــرى االطــاع علــى إقــراره‬\n‫املصــادق عليــه شــرع ًا املــدون صفحــة (‪ )1‬بدفتــر التحقيــق املرفــق علــى‬\n‫اللفــة رقــم (‪ )20‬فوجــد يتضمــن علــى إقــرار بتاريــخ ‪1432/08/12‬ه ـ‬\n‫وهــذا نصــه (أقرأنــا ‪................‬باكســتاني اجلنســية مبوجــب جوازســفر‬\n‫رقــم (‪ ) ................‬دون إجبــار أو إكــراه مــن أحــد وأنــا بكامــل قــواي‬\n‫العقليــة بأنــي قمــت بتهريــب (‪ )116‬كبســولة إلــى داخــل اململكــة وذلــك‬\n‫عــن طريــق أحشــائي وعنــد وصولــي إلــى مطــار الريــاض مت القبــض علــي‬\n‫ومت إنــزال مائــة وســتة عشــر كبســولة مــن أحشــائي وكان غرضــي‬\n‫وقصــدي مــن تهريــب الكبســوالت إلــى اململكــة هــو احلصــول علــى‬\n‫املبلــغ املالــي قــدره مائــة ألــف روبيــة باكســتانية وتأشــيرة عمــل يف‬\n‫اململكــة العربيــة الســعودية باإلضافــة إلــى تذاكــر ســفر وكان‬\n‫ســيعطيني إياهــا شــخص يف باكســتان ذكــرت اســمه للمحقــق كمــا‬\n‫أقــر بأنــه عندمــا كنــت يف باكســتان حضــر إلــي هــذا الشــخص‬\n‫وعــرض علــي تهريــب الكبســوالت يف األحشــاء وإدخالهــا إلــى اململكــة‬\n‫مقابــل أن يعطينــي مائــة ألــف روبيــة وتأشــيرة عمــل وتذاكــر ســفر ويف‬\n‫يــوم الســفر أحضــر إلــي هــذا الشــخص الكبســوالت وقمــت بابتالعهــا‬\n‫وقدمــت إلــى الســعودية عــن طريــق الطائــرة ثــم قبــض علــي وقمــت بإنزال‬\n‫الكبســوالت التــي قمــت بابتالعهــا ســابق ًا هــذا إقــراري وعليــه أصــادق‬\n‫بعــد ترجمتــه لــي مــن قبــل املترجــم وقــد صــدق هــذا االعتــراف مــن‬\n\n\n                                                                                        ‫‪40‬‬\n\f     ‫احملكمــة العامــة بالريــاض كمــا جــرى االطــاع علــى إقــراره حتقيقــا‬\n     ‫املــدون علــى صفحــة رقــم (‪ )3-2-1‬بدفتــر التحقيــق املرفــق علــى اللفــة‬\n     ‫رقــم (‪ )19‬فوجــد يتضمــن علــى س‪ /‬أنــت متهم بتهريب (‪ )116‬كبســولة‬\n     ‫بلــغ وزنهــا (‪ )955,1‬جــرام عــن طريــق أحشــائك مــن الهرويــن املخــدر فمــا‬\n     ‫قولــك ج‪ /‬نعــم أنــا هربــت كبســوالت ولــم أكــن أعلــم أنهــا هرويــن س‪/‬‬\n     ‫أفدنــا بالتفصيــل كيــف مت القبــض عليــك ج‪ /‬أفيدكــم عندمــا كنــت‬\n     ‫يف باكســتان عــرض علــي شــخص يدعــى ‪ ................‬وذلــك يف‬\n     ‫قريتــي‪.........‬يف مدينــة ‪.........‬وذلــك مقابــل مبلــغ مائــة ألــف روبيــة‬\n     ‫باكســتانية وأعطانــي تأشــيرة عمــل وتذاكــر إلــى الســعودية وذلــك‬\n     ‫مقابــل أن أقــوم بتهريــب كبســوالت ال أعلــم مابداخلهــا عــن طريــق‬\n     ‫أحشــائي فوافقــت علــى ذلــك ويف نفــس يــوم الســفر أعطانــي املدعــو‬\n     ‫‪.........‬الكبســوالت وذهبنــا إلــى مــكان يعلمــه املدعــو ‪ ................‬فقمــت‬\n     ‫بابتــاع الكبســوالت ثــم توجهنــا إلــى املطــار يف ‪.........‬ومنــه إلــى مدينــة‬\n     ‫كراتشــي ثــم توجهنــا إلــى الســعودية ويف املطــار مت الكشــف علــي‬\n     ‫واتضــح أن بداخلــي الكبســوالت فقبــض علــي س ‪ /‬مــاذا أخبــرك‬\n     ‫املدعــو ‪ ................‬مــا بداخــل الكبســوالت ج‪ /‬لــم يخبرنــي بشــيء س‪/‬‬\n     ‫ملــاذا لــم تســأل ‪.........‬يف حينهــا مــا بداخــل الكبســوالجت‪ /‬ألنــه كان‬\n     ‫وعدنــي مبقابــل املبلــغ املالــي والتذاكــر وتأشــرية العمــل س‪ /‬هــل كنت‬\n     ‫تعلــم أنهــا ومــا بداخلهــا ممنوعــة ج‪ /‬ال س‪ /‬ملــاذا إذا تقــوم بإدخــال‬\n     ‫الكبســوالت وتهريبهــا يف أحشــائك مــع علمــك بأنهــا ليســت ممنوعــة‬\n     ‫ج‪ /‬ألن‪................‬قــال لــي أن هــذه الكبســوالت ال ينفــع أن تذهــب بهــا‬\n     ‫وهــي يف الشــنطة ولكــن عــن طريــق أحشــائك س‪ /‬أقــررت عنــد ســماع‬\n     ‫أقوالــك أنــك كنــت تعلــم أن مــا بداخــل الكبســوالت هــو الهرويــن‬\n\n\n‫‪41‬‬\n\f‫املخــدر واآلن تنكــر ذلــك فمــا قولــك ج‪ /‬أنــا لــم أقــل لهــم ذلــك وهــم مــن‬\n‫أخبرونــي أنهــا هرويــن مخــدر س‪ /‬قيامــك بتهريــب الهرويــن عــن طريــق‬\n‫أحشــائك يــدل علــى علمــك بأنهــا هرويــن ويــدل علــى مراوغتــك يف‬\n‫االجابــة فأنصحــك بقــول احلقيقــة فمــا قولــك ج‪ /‬أنــا بعــد القبــض علــي‬\n‫عرفــت أنهــا هرويــن س‪ /‬اتفاقــك مع‪................‬علــى مبلــغ مالــي‬\n‫وحصولــك علــى تأشــيرة عمــل يف اململكــة يــدل ويؤكــد علــى علمــك‬\n‫بــأن مــا هربــت بداخــل أحشــائك هــو مــن الهرويــن املخــدر فمــا قولــك ج‪/‬‬\n‫لــم أقــل إال احلقيقــة س‪ /‬هــل ســبق لــك أن هربــت مــواد مخــدرة إلــى‬\n‫اململكــة ج‪ /‬هــذه أول مــرة أهــرب وهــي أول مــرة أقــدم إلــى الســعودية‬\n‫س‪ /‬أعطنــا معلومــات كافيــه عــن املدعــو ‪.........‬ج‪ /‬املدعــو ‪.........‬‬\n‫يسكن يف ‪.........‬يف نفس القرية التي أسكن فيها وجواله (‪)................‬‬\n‫س‪ /‬لــم كنــت تنــوي تســليم الكبســوالت التــي يف أحشــائك ج‪ /‬ال أعلــم‬\n‫حيــث كان أتفاقــي مــع أســتقل ســيارة أجــرة ثــم أتصــل علــي ‪................‬‬\n‫ويخبرنــي عــن الشــخص الــذي ســوف اســلمه الكبســوالت س‪ /‬هــل‬\n‫قمــت باالتصــال مــن جوالــك املضبــوط معــك علــى املدعــو ‪ ................‬ج‪/‬‬\n‫نعــم صحيــح قمــت بذلــك س‪ /‬ضبــط معــك مبلــغ مالــي قــدره مائــة ريــال‬\n‫فلمــن تعــود ج‪ /‬أعطانــي إيــاه كمصاريــف ســفر واملبالــغ األخــرى (‪)350‬‬\n‫روبيــة باكســتاني تعــود لــي وهــي مصــرويف الشــخصي س‪ /‬هــا تتعاطــى‬\n‫أي مــواد مخــدرة ج‪ /‬ال وال يوجــد علــي ســوابق وليــس لــدي أقــوال أخــرى‬\n‫وإننــي أصــادق علــى أقوالــي كمــا جــرى االطــاع علــى اعترافــه‬\n‫مبحضرســماع أقوالــه األوليــة املــدون تفصيــا علــى اللفــة رقــم (‪-10-9‬‬\n‫‪ )11‬فوجــد يتضمــن علــى محضــر ســماع أقــول بتاريــخ ‪1432/08/11‬ه ـ‬\n‫صــادر مــن املديريــة العامــة ملكافحــة املخــدرات س‪ /‬أعطنــا املعلومــات‬\n\n\n                                                                                      ‫‪42‬‬\n\f     ‫اإلحصائيــة عــن نفســك ج‪ ................ /‬باكســتاني اجلنســية س‪ /‬كيــف‬\n     ‫مت القبــض عليــك وملــاذا ج‪ /‬مت القبــض علــي مــن قبــل موظــف اجلمــارك‬\n     ‫عنــد تفتيشــي أشــتبه يف وضعــي وعرضنــي علــى األشــعة س‪ /‬أنــت متهــم‬\n     ‫بتهريــب مــا عــدده (‪ )116‬كبســولة يشــتبه تكــون هرويــن فمــا قولــك‬\n     ‫ج‪ /‬هــذا صحيــح قــد هربــت يف أحشــائي عــدد (‪ )116‬كبســولة هرويــن‬\n     ‫مخــدر س‪ /‬مــا هــو قصــدك مــن حيــازة مــا مت ضبطــه معــك ج‪ /‬لغــرض‬\n     ‫إيصالهــا إلــى مدينــة الريــاض س‪ /‬مــن أيــن حصلــت علــى الكميــة‬\n     ‫املضبوطــة بحوزتــك ج‪ /‬حصلــت عليهــا عــن طريــق شــخص يدعــى يف‬\n     ‫باكســتان ومعــه جــوال رقــم (‪ )................‬س‪ /‬هــل تعاطيــت شــيء ممــا‬\n     ‫مت ضبطــه بحوزتــك وهــل ســبق القبــض عليــك يف قضيــة مخــدرات ج‪ /‬ال‬\n     ‫س‪ /‬كــم ضبــط معــك مبلــغ مالــي وماهــي عالقتــك بــه ج‪ /‬إنــه مبلــغ‬\n     ‫بســيط (‪ )100‬ســعودي و(‪ )150‬روبيــة وهــو مصــرويف س‪ /‬كــم عــدد‬\n     ‫الســوابق اجلنائيــة عليــك ج‪ /‬ال يوجــد س‪ /‬مــن هــو الشــخص الــذي ســوف‬\n     ‫تقــوم بتســليم هــذه الكميــة لــه داخــل اململكــة وكيــف ســتتواصل معــه‬\n     ‫ج‪ /‬طلــب منــي ‪.........‬االتصــال عليــه مــن أي جــوال لكــي يعطينــي رقــم‬\n     ‫الــذي ســوف يســتقبلني مبدينــة الريــاض حــن وصولــي مدينــة الريــاض‬\n     ‫س‪ /‬كيــف ســتقوم بإنــزال الكبســوالت املضبوطــة بداخــل أحشــائك‬\n     ‫ج‪ /‬بواســطة إنزالهــا س‪ /‬مــا هــو املبلــغ الــذي تتقاضــاه مقابــل نقــل هــذه‬\n     ‫الكميــة إلــى اململكــة وهــل اســتلمته ج‪ /‬املدعــو‪ ................‬أخبرنــي يف‬\n     ‫حــن وصولــي مدينــة الريــاض وإنــزال الكبســوالت ســوف يعطــي أحــد‬\n     ‫أقربائــي يف باكســتان (‪ )1600‬روبيــة لــكل كبســولة س‪ /‬هــل لــدك‬\n     ‫أقــوال أخــرى ج‪ /‬ال س‪ /‬أتصــادق علــى أقوالــك ج‪ /‬نعــم كمــا جــرى‬\n     ‫االطــاع علــى محضــر القبــض املرفــق علــى اللفــة رقــم (‪ )2‬فوجــد‬\n\n\n‫‪43‬‬\n\f                                                            ‫يتضمن على محضر‬\n‫ضبــط صــادر مــن جمــرك مطــار امللــك خالــد الدولــي رقــم ‪.........‬‬\n‫يف ‪1432/08/11‬ه ـ للراكب‪................‬أنــه أثنــاء تواجــد املراقــب‬\n‫اجلمركــي بالصالــة الدوليــة رقــم (‪ )2‬مت االشــتباه بالراكــب ومت‬\n‫إحالتــه إلــى جهــاز األشعةوبالكشــف عليــه ظهــرت النتيجــة بوجــود‬\n‫أجســام غريبــة داخــل أحشــائه ومت حجــزه حيــث قــام بإنــزال عــدد‬\n‫(‪ )116‬كبســولة حتتــوي علــى مــادة بنيــة اللــون يشــتبه أن تكــون‬\n‫مــن مــادة الهيرويــن املخــدر بلــغ وزنهــا اإلجمالــي مــع األغلفــة (‪)955,1‬‬\n‫جــرام تقريبــا اســتقطع منهــا ثــاث عينــات وزن كل عينــة واحــد‬\n‫جــرام تقريبــا ورصصــت العينــات كمــا هــو موضــح مبحضــر حتريــز‬\n‫العينــات وكذلــك باقــي الكميــة وعينــه رابعــة وزنهــا خمســة جرامــات‬\n‫ســلمت ملنــدوب املكافحــة باملطــار مرصصــه بالرقــم (‪ )116601‬ومت‬\n‫الترصيــص بحضــور منــدوب مكافحــة املخــدرات باملطــار كمــا‬\n‫جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق لفــة رقــم‬\n‫(‪ )27‬فوجــد يتضمــن علــى تقريــر صــادر مــن املديريــة العامــة للشــؤون‬\n‫الصحيــة مبنطقــة الريــاض مركــز مراقبةالســموم والكيميــاء الطبيــة‬\n‫الشــرعية رقــم ‪.........‬يف ‪1432/08/17‬ه ـ أنــه بالتحليــل الكيميائــي‬\n‫الشــرعي حملتويــات احلــرز املرســل بالرصاصــة اجلمركيــة رقــم (‪).........‬‬\n‫وبداخلــه واحــد جــرام مــن مــادة مشــتبه فيهــا مت ضبطهــا مبوجــب‬\n‫محضــر الضبــط رقــم ‪.........‬وتاريــخ ‪1432/08/11‬ه ـ واملرفــق بخطــاب‬\n‫ســعادة مديــر عــام جمــرك مطــار امللــك خالــد الدولــي ‪/331‬س ‪14/‬‬\n‫وتاريــخ ‪1432/08/12‬ه ـ ثبــت لدينــا اآلتــي‪ - :‬احلــرز املرســل بالرصاصــة‬\n‫اجلمركيــة رقــم (‪ )................‬عبــارة عــن مســحوق مــن مــادة لونــا مييــل‬\n\n\n                                                                                     ‫‪44‬‬\n\f     ‫للبنــي تــزن واحــد جــرام ثبــت احتــواء املســحوق ملــادة الهرويــن وهــو مــن‬\n     ‫املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة واملبلــغ بتعميــم ســمو وزيــر الداخليــة رقــم‬\n     ‫‪ 89400/19‬يف ‪1426/10/25‬ه ـ الصــادر باملرســوم امللكــي رقــم‬\n     ‫م ‪ 39 /‬وتاريــخ ‪1426/07/08‬ه ـ ‪ -‬اســتهلكت العينــة يف التحليــل‬\n     ‫وبعــرض مــا تقــدم علــى املدعــى عليــه أجــاب بواســطة املترجــم قائــا‬\n     ‫كمــا ذكرتــك لكــم فإننــي اشــتريت تأشــيرة عمــل يف الســعودية مــن‬\n     ‫شــخص مائــة وثمانــن ألــف روبيــة ودفعــت لــه مائــة ألــف روبيــة وبقــي لــه‬\n     ‫ثمانــن ألــف روبيــة وقبــل ســفري علــى الطائــرة بحوالــي اثنتــي عشــرة‬\n     ‫ســاعة شــربت عصيــرا لــدى املدعو‪................‬وبعدهــا فقــدت الوعــي‬\n     ‫ولــم أحــس بشــيء حتــى صعــدت الطائــرة ويف الطائــرة أحسســت بألــم‬\n     ‫يف بطنــي ولــم أكتشــف مــايف بطنــي إال بعــد وصولــي إلــى الســعودية‬\n     ‫وحينهــا عرفــت أنــه مت اســتغاللي مــن قبــل عصابــة مخــدرات لتهريــب‬\n     ‫مــادة الهيرويــن املخــدر يف أحشــائي وأنــا ال أعلــم عــن ذلــك شــيئا إطالقــا‬\n     ‫و لــم أقصــد التهريــب إطالقــا هكــذا قــرر فبنــاء علــى ماتقــدم مــن‬\n     ‫الدعــوى واإلجابــة وبنــاء علــى مــا تضمنــه إقــرار املدعــي عليــه املصــادق‬\n     ‫عليــه شــرعا بتهريــب (‪ )116‬كبســولة يف أحشــائه إلــى داخــل اململكــة‬\n     ‫مقابــل مبلــغ مالــي وفيــزة عمــل يف اململكــة وبنــاء علــى مــا تضمنــه‬\n     ‫محضــر القبــض أنــه وبعــد االشــتباه باملدعــى عليــه مت إحالتــه إلــى جهــاز‬\n     ‫األشــعة وتبــن وجــود أجســام غريبــة ثــم إنــه أنــزل مــن بطنــه (‪)116‬‬\n     ‫كبســولة وبنــاء علــى التقريــر الكيميائــي املتضمــن ثبــوت إيجابيــة‬\n     ‫العينــة ملــادة الهيرويــن املخــدر وبنــاء علــى املــادة الســابعة والثالثــن مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــرة (أ) مــن البنــد أوال‬\n\n\n‫‪45‬‬\n\f‫فقــد ثبــت لدينــا إدانــة املدعــى عليــه بتهريــب (‪ )116‬كبســولة حتتــوي‬\n‫علــى مــادة الهيرويــن ومبــا أن مادفــع بــه املدعــى عليــه مــن أنــه شــرب‬\n‫العصيــر لــدى املدعــو (‪ ) ................‬وأنــه فقــد الوعــي بعدهــا ولــم يحــس‬\n‫بشــيء إال بعــد ركوبــه الطائــرة ولــم يعلــم مــا يف بطنــه إال بعــد وصولــه‬\n‫إلــى الســعودية دفــع يحتمــل وقوعــه ومبــا أنــه يحتــاط يف الدمــاء مــاال‬\n‫يحتــاط يف غيرهــا فعــن عائشــة رضــي اهلل عنهــا قالــت قــال رســول‬\n‫اهلل صلــى اهلل عليــه وســلم (فــإن وجــدمت للمســلم مخرجــا فخلواســبيله‬\n‫فــإن اإلمــام ألن يخطــئ يف العفــو خيــر لــه مــن أن يخطــئ يف العقوبــة)‬\n‫أخرجــه الترمــذي وغيــره وبنــاء علــى مــا جــاء يف ( ثانيــا ) مــن املــادة‬\n‫الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املتضمنــة أنــه يجــوز للمحكمــة وألســباب تقدرهــا النــزول عــن عقوبــة‬\n‫القتــل إلــى عقوبــة الســجن لــذا فقــد قررنــا تعزيــره وذلــك بســجنه خمــس‬\n‫عشــرة ســنة وجلــده خمســن جلــدة تكــرر عليــه خمــس عشــرة مــرة بــن‬\n‫كل مــرة وأخــرى مــدة شــهرين وغرامــة ماليــة قدرهــا مائــة ألــف ريــال‬\n‫ومصــادرة هاتفــه اجلــوال بشــريحته واملبلــغ املضبــوط بحوزتــه وقــدره مائة‬\n‫ريــال ونوصــي بإبعــاده عــن البــاد بعــد انتهــاء مالــه وماعليــه مــن حقــوق‬\n‫ومبــا تقــدم قضينــا وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة بــه وقــرر املدعــي العــام عــدم قناعتــه باحلكــم وطلب االســتئناف‬\n‫فأجيــب لطلبــه واســتلم نســخة مــن احلكــم هــذا اليــوم وأفهــم بــأن مــدة‬\n‫االعتــراض ثالثــن يومــا تبــدأ مــن تاريــخ اســتالمه نســخة احلكــم وإذا‬\n‫لــم يقــدم الالئحــة االعتراضيــة خــال املــدة املذكــورة ســقط حقــه يف‬\n‫االعتــراض ويرفــع احلكــم لالســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/07/16‬ه ـ‬\n\n\n                                                                                       ‫‪46‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫مالحظــا عليهــا مبوجــب قرارهــم رقــم ‪ ................‬يف ‪1433/12/29‬ه ـ‬\n     ‫فقــد الحــظ أصحــاب الفضيلــة مايلــي أوال ‪ /‬طالــب املدعــي العــام بقتــل‬\n     ‫املدعــى عليــه تعزيــرا علــى ضــوء الفقــرة (‪ )1‬مــن البنــد أوال مــن املــادة‬\n     ‫(‪ )37‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ولــم جنــد أن‬\n     ‫أصحــاب الفضيلــة تطرقــوا يف حكمهــم لهــذا املطلــب بشــيء ثانيــا ‪/‬‬\n     ‫أوصــى أصحــاب الفضيلــة بإبعــاد املدعــى عليــه عــن البــاد وهــذا محــل‬\n     ‫نظــر واملتعــن أن يكــون اإلبعــاد علــى ضــوء املــادة رقــم (‪ )56‬مــن ذات‬\n     ‫النظــام ال التوصيــة بذلــك إلكمــال مــا يلــزم عليــه جنيــب بأنــه لــم يظهــر‬\n     ‫لنــا قتــل املدعــى عليــه تعزيــرا ألن مــا دفــع بــه املدعــى عليــه يحتمــل‬\n     ‫وقوعــه وبخصــوص املالحظــة الثانيــة فقدقررنــا إبعــاد املدعــى عليــه‬\n     ‫عــن البــاد بعــد تنفيــذ العقوبــة احملكــوم بهــا وذلــك بنــاء علــى املــادة‬\n     ‫‪ 2/56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وأمــا فضيلــة‬\n     ‫القاضي‪................‬فقــد انتقــل عملــه إلــى محكمــة االســتئناف يف مدينــة‬\n     ‫حائــل وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه‬\n                                                    ‫وســلم ‪ .‬حــرريف ‪1434/02/19‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n     ‫اخلماســية مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‪................‬‬\n     ‫وتاريــخ ‪1434/2/23‬ه ـ املرفــق بهــا القــرار الصــادر مــن أصحــاب‬\n     ‫الفضيلــة القضــاة باحملكمــة الشــيخ‪................ /‬برقــم ‪................‬‬\n     ‫وتاريخ‪1433/7/16‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪................ /‬‬\n     ‫يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم أصحــاب الفضيلــة علــى‬\n\n\n‫‪47‬‬\n\f‫النحــو املفصــل فيــه وباإلطــاع علــى ماأجــاب بــه أصحــاب الفضيلــة‬\n‫وأحلقــوه بالقــرار وصــورة ضبطــه جواب ـ ًا علــى قرارنــا رقــم ‪................‬‬\n‫وتاريــخ ‪1433/12/29‬ه ـ قررنــا باألكثريــة املصادقــة علــى احلكــم بعــد‬\n                                                          ‫اإلجــراء واهلل املوفــق‪.‬‬\n\n\n\n\n                                                                                      ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":35,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0fd88ebec238c0ff152539674879662b89c978105a38bc28aec5dc93026fd9f4","normalized_text_hash":"b7cdc3c9511151c9ef4703101a4b1eeef502a876e9748694b1ece3694e166563","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p35-33345920"},{"id":"0f975492-cb20-53dd-ad98-5a59913314ae","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب احلشيش املخدر -اقرار املدعى عليه -ثبوت إدانته -التعزير بالسجن واجللد والغرامة واإلبعاد عن","document_number":"33331714","case_number":"3336938","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجازان","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/7","year":"1434","subject":"مخدرات -تهريب احلشيش املخدر -اقرار املدعى عليه -ثبوت إدانته -التعزير بالسجن واجللد والغرامة واإلبعاد عن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪33331714 :‬تاريخه‪1434/7/7 :‬هـ‬\n                        ‫رقم الدعوى‪3336938 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3410075‬تاريخه‪1434/1/12 :‬هـ‬\n\n\n     ‫حتقيقــا‬\n        ‫ً‬       ‫مخــدرات ‪ -‬تهريــب احلشــيش املخــدر‪ -‬اقــرار املدعــى عليــه‬\n     ‫‪ -‬ثبــوت إدانتــه ‪ -‬التعزيــر بالســجن واجللــد والغرامــة واإلبعــاد عــن‬\n                                                                       ‫البــاد‪.‬‬\n\n\n\n\n     ‫(أول) مــن املــادة (‪)37‬‬\n                          ‫الفقــرة (‪ )1‬مــن املــادة (‪ )3‬والفقــرة (‪ )5‬مــن البنــد ً‬\n     ‫والفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واﻤﻟﺆﺛﺮات‬\n                                                                           ‫اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n     ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بتهريــب احلشــيش املخــدر‪،‬‬\n     ‫بقصــد الكســب املــادي ‪ ،‬مت القبــض علــى املدعــى عليــه مــن قبــل‬\n     ‫دوريــات حــرس احلــدود وبحوزتــه مــادة احلشــيش واثبــت التقريــر ايجابيــة‬\n     ‫العينــة ملــادة احلشــيش املخــدر ‪ ،‬أقــر املدعــى عليــه بالتهريــب‪ ،‬أثبــت‬\n     ‫التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى احلشــيش‬\n     ‫املخــدر‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى عليــه‪ ،‬بالقتــل تعزيــر ًا‬\n     ‫حكمــت احملكمــة بثبــوت إدانــة املدعــى عليــه بتهريــب احلشــيش‪،‬‬\n     ‫فقــررت احملكمــة احلكــم تعزيــره بالســجن ثمــان ســنوات اعتبــار ًا مــن‬\n     ‫تاريــخ القبــض‪ ،‬وجلــده ثمامنائــة جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n\n‫‪49‬‬\n\f‫خمســون جلــدة بــن كل دفعــة واألخــرى عشــرة أيــام‪ ،‬تغرميــه مبلــغ مائــة‬\n‫ألــف ري ــال خلزينــة الدولــة‪ ،‬إبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‬\n‫وعــدم الســماح لــه بالدخــول للبــاد وقــرر املدعــى عليه قناعتــه باحلكم‪،‬‬\n                        ‫مت تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن كل مــن ‪ ................‬القضــاة‬\n‫باحملكمــة العامــة بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامة بجازان برقــم ‪ ................‬وتاريخ ‪1433/01/15‬‬\n‫ه ـاملقيدة باحملكمة برقم ‪ ................‬وتاريخ ‪ 1433/01/11‬هـ ففي يوم‬\n‫األحــد املوافــق‪ 1433/06/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬وفيها‬\n‫حضــر املدعــي العام‪................‬املكلــف باالدعــاء العــام مــن ســعادة‬\n‫رئيــس هيئــة التحقيــق واالدعــاء العــام بجــازان مبوجــب التعميــد رقــم‬\n‫(‪ )4018‬وتاريــخ ‪1433/2/2‬ه ـ وحضــر حلضــوره املدعى عليــه ‪................‬‬\n‫مينــي اجلنســية بالبطاقــة البديلــة املؤقتــة رقــم (‪ )................‬وادعــى املدعــي‬\n‫العــام بقولــه بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n‫مبنطقــة جــازان أدعــي علــى املذكــور أعــاه فإنــه يف يــوم اجلمعــة املوافــق‬\n‫‪1432/11/23‬ه ـ وأثنــاء قيــام إحــدى دوريــات حــرس احلــدود بواجبهــا‬\n‫شــمال غــرب قريــة ‪.........‬ألقــت القبــض علــى املدعــي عليــه أثنــاء قدومــه‬\n‫مــن األراضــي اليمنيــة إلــى األراضــي الســعودية ســير ًا علــى األقــدام‬\n‫بطريقــة غيــر نظاميــة‪ ،‬وبتفتيشــه ضبــط بحوزتــه علــى(‪ )6‬ســت بالطــات‬\n‫مــن مــادة يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنها(‪6‬كجــم)‬\n‫ســتة كيلوجــرام‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي رقــم‪.........‬‬\n                                                                                            ‫‪50‬‬\n\f     ‫الصــادر مــن مركــز الســموم والكيمياءالطبيةالشــرعية مبنطقــة‬\n     ‫مكــة املكرمــة إيجابيــة العينــة املرســلة مــن الكميــة املهربــة املضبوطــة‬\n     ‫للحشــيش املخــدر واحتواءهــا علــى املــادة الفعالــة لــه املــدرج ضمــن‬\n     ‫اجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬هــ‪ .‬أودع‬\n     ‫شــعبة ســجن جــازان العــام كــون جرميتــه مــن اجلرائــم املوجبــة للتوقيــف‬\n     ‫اســتناد ًا للقــرار الــوزاري رقــم (‪ )................‬يف ‪1428/7/9‬ه ـ املبنــي علــى‬\n     ‫املــادة (‪ )112‬مــن نظــام االجــراءات اجلزائيــة‪ .‬وباســتجواب املدعــي عليــه‬\n     ‫ومواجهتــه بالتهمــة املنســوبة إليــه أقــر بأنــه مت القبــض عليــه بعــد قيامــه‬\n     ‫بتهريــب كميــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا (‪6‬كجــم) ســتة‬\n     ‫كيلوجــرام أعطــاه إياهــا يف ‪ ......‬اليمــن شــخص مينــي يدعــى‪................/‬‬\n     ‫(جــرى مخاطبــة إدارة مكافحــة املخــدرات بجــازان للتنســيق مــع‬\n     ‫اجلهــات املختصــة يف اليمــن لوضعــه حتــت املراقبــة والقبــض عليــه باجلــرم‬\n     ‫املشــهود) ويرغــب إيصالهــا إلــى الــوادي بجــوار كبــري أحــد املســارحة‬\n     ‫باألراضــي الســعودية لشــخص (ال يعرفــه) مقابــل أجــر مــادي قــدره‬\n     ‫(‪ )1800‬ألــف وثمامنائــة ريــال ســعودي وقــد اســفر التحقيــق عــن توجيــه‬\n     ‫االتهــام للمدعــي عليــه بارتكابــه جرميــة تهريــب مــا وزنه(‪6‬كجــم) ســتة‬\n     ‫كيلوجــرام مــن مــادة احلشــيش املخــدر مــن اليمــن إلــى الســعودية بقصــد‬\n     ‫االجتــار ‪،‬املجــرم مبوجــب الفقــرة (األولــى) مــن املــادة (الثالثــة) مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقلية‪،‬الصــادر باملرســوم امللكــي‬\n     ‫رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وحيــث إن مــا أقــدم عليــه املدعــي عليه فعل‬\n     ‫محــرم و معاقــب عليــه شــرع ًا و مجــرم ومعاقــب عليــه نظامــا مبوجــب‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه األصليــة‬\n\n\n‫‪51‬‬\n\f‫والتكميليــة لــذا اطلــب ‪ /‬اثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n‫بالقتــل تعزيــر ًا وفقـ ًا للفقــرة رقــم (‪ )1‬مــن البنــد (أوالً) مــن املــادة الســابعة‬\n‫والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللــك يرقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ هــذه دعــواي وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫ا هكــذا أجــاب وباالطــاع علــى أوراق‬           ‫العــام صحيــح جملــة وتفصي ـ ً‬\n‫املعاملــة وجــد بهــا التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكةاملكرمــة‬\n‫رقــم (‪ ).........‬وتاريــخ ‪1432/12/11‬ه ـ املتضمــن إيجابيــة العينــة املرســلة‬\n       ‫مــن الكميــة املضبوطــة ملــادة احلشــيش املرفــق باملعاملــة لفــة (‪)26‬‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه‬        ‫فبنـ ً‬\n‫علــى دعــوى املدعــي العــام وبعــد االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي ونظــر ًا لضــرر احلشــيش املخــدر علــى الضــرورات اخلمــس‬\n‫التــي جــاءت الشــرائع باحملافظــة عليهــا وبعــد اإلطــاع علــى املــادة‬\n‫(‪ )60،56،37‬مــن نظــام املخــدرات واملؤثــرات العقليــة لــذا فقــد ثبــت‬\n‫لدينــا إدانــة املدعــى عليــه بتهريــب مــا وزنــه (‪6‬كجــم) ســتة كيلوجــرام‬\n‫مــن مــادة احلشــيش املخــدر مــن اليمــن إلــى الســعودية ونظــر ًا لصغــر ســن‬\n‫املدعــى عليــه فقــد حكمنــا مبــا يلــي‪ :‬أو ًال رد طلــب املدعــي العــام قتــل‬\n‫املدعــى عليــه تعزيــر ًا ثانياً‪:‬تعزيــر املدعــى عليــه وذلــك بســجنه ثمــان‬\n‫ســنوات تبــدأ مــن تاريــخ القبــض عليــه وجلــده ثمامنائــة جلــده مفرقــة‬\n‫علــى دفعــات كل دفعــة خمســون جلــدة بينهــا عشــرة أيــام ثالث ـاً‪ :‬تغــرمي‬\n‫املدعــى عليــه مبلــغ مائــة ألــف ريــال غرامــة تــؤول للخزينــة العامــة للدولــة‬\n‫رابعاً‪:‬إبعــاد املدعــى عليــه عــن البــاد بعــد انتهــاء محكوميتــه وعــدم‬\n\n\n                                                                                              ‫‪52‬‬\n\f     ‫الســماح لــه بالدخــول للمملكــة وبعــرض احلكــم علــى املدعــي العــام‬\n     ‫واملدعــى عليــه قنــع بــه املدعــى عليــه وقــرر املدعــي العــام عــدم القناعــة‬\n     ‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة يقدمهــا فأجيــب‬\n     ‫لطلبــه وأفهــم باملراجعــة بعــد عشــرة أيــام الســتالم صــورة مــن احلكــم‬\n     ‫لتقــدمي اعتراضــه عليــه وأفهــم بالتعليمــات املتعلقــة بهــذا اخلصــوص‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                          ‫حــرر يف ‪1433/6/22‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعدففــي يــوم الثالثــاء املوافــق‪ 1434/02/26‬ه ـ‬\n     ‫افتتحــت اجللسةالســاعة العاشــرة والنصــف وقــد عــادت املعاملــة مــن‬\n     ‫محكمــة االســتئناف مبنطقــة عســير بكتــاب فضيلــة رئيســها رقــم‬\n     ‫(‪ )................‬وتاريــخ ‪1434/1/24‬ه ـ وبرفقــه قــرار الدائــرة األولــى‬\n     ‫لتدقيــق القضايــا اخلماســية رقــم(‪ )................‬وتاريخ‪1434/1/12‬ه ـ‬\n     ‫ونــص احلاجــة منــه (وبدارســة القــرار الشــرعي وصــورة ضبطــه والالئحــة‬\n     ‫االعتراضيــة وأوراق املعاملــة لوحــظ مايلــي‪ :‬أوالً‪ /‬لتقييــد الالئحــة‬\n     ‫اإلعتراضيــة املقدمــة مــن املدعــي العــام بقيــد احملكمــة ثانياً‪/‬صــورة‬\n     ‫الضبــط الصفحــة األولــى خاليــة مــن توقيــع املدعــي العــام والصفحــة‬\n     ‫األخيــرة خاليــة مــن توقيــع فضيلــة القاضــي الشــيخ ‪ ................‬وهــذا البد‬\n     ‫منــه يف الضبــط) فعلــى أصحــاب الفضيلــة مالحظــة ماذكــر وإحلــاق‬\n     ‫مــا يجرونــه يف الضبــط وصورتــه والقــرار الشــرعي منثــم تعــاد املعاملــة‬\n     ‫إلكمــال الزمهــا واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n     ‫وصحبــه وســلم قاضــي اســتئناف (‪ )................‬وجنيــب أصحاب الفضيلة‬\n     ‫علــى مــاورد مــن مالحظــات بأنــه أجــري الــازم حيالهــا علمـ ًا أن فضيلــة‬\n     ‫الشــيخ ‪ ................‬القاضــي املشــارك يف نظــر هــذه الدعــوى قدانتقــل‬\n\n\n‫‪53‬‬\n\f‫مــن هــذه احملكمــة إلــى احملكمــة اجلزائيــة باخلبــر وقررنــا بعــث املعاملــة‬\n‫حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/5/29‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الثامنــة وقــد وردنــا خطــاب فضيلــة‬\n‫رئيــس محكمــة اإلســتئناف مبنطقــة عســير رقــم (‪ )................‬وتاريــخ‬\n‫‪1434/4/23‬ه ـ واملرفــق بــه قــرار الدائــرة اخلماســية األولــى لتدقيــق‬\n‫القضايــا مبحكمــة االســتئناف مبنطقــة عســير برقــم (‪)................‬‬\n‫وتاريــخ ‪1434/04/03‬ه ـ ونــص احلاجــة منــه (وحيث ســبق دراســة القرار‬\n‫الشــرعي وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫أصحــاب الفضيلــة وأحلقــوه بالقــرار الشــرعي بنــاء علــى قرارنــا رقــم‬\n‫(‪ )................‬وتاريخ‪1434/01/12‬ه ـ تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم قاضــي ‪ )................‬وحتــى ال يخفــى جــرى إحلاقــه‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                 ‫‪1434/05/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اخلماســية مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بجــازان برقــم‬\n‫‪ ................‬يف ‪1434/03/10‬ه املرفــق بهــا القــرار الشــرعي الصــادر مــن‬\n‫أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ................ /‬والشــيخ‪/‬‬\n‫‪ ................‬والشــيخ‪ ................/‬برقــم‪ ................‬تاريــخ ‪1433/7/7‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪( ................/‬مينــي اجلنســية) التهامــه‬\n\n\n                                                                                        ‫‪54‬‬\n\f     ‫يف قضيــة (تهريــب احلشــيش املخــدر) علــى الصفــة املوضحــة يف القــرار‬\n     ‫املتضمــن حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪،‬‬\n     ‫وحيــث ســبق دراســة القــرار الشــرعي وصــورة ضبطــه وأوراق املعاملــة‬\n     ‫‪ ،‬وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة وأحلقــوه بالقــرار‬\n     ‫ـاء علــى قرارنــا رقــم ‪ ................‬وتاريــخ ‪1434/1/12‬ه ـ‬\n                                                                   ‫الشــرعي بنـ ً‬\n     ‫تقــررت املوافقــة علــى احلكــم بعــد االجــراء األخيــر‪ ،‬واهلل املوفــق و‬\n                      ‫صلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪55‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":49,"source_page_end":55,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"34967059692929f44967bd9ae44141e42fa8d59b4e6ef564dd45ce0058567442","normalized_text_hash":"1fc9b49b5fcc13456e98d515f8d81ef0530a7306251a5e20c9484bb45de90454","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p49-33331714"},{"id":"5847c607-3d85-5086-b31a-2f2e3d4b0c85","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب املخدرات -إقرار مصدق شرع ا -املشاركة يف جلب املخدرات من اخلارج -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليهم -التعزير بالسجن واجللد وغرامة مالية ومصادرة اجلوال وإلغاء الشريحة.","document_number":"3452825","case_number":"3417873","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"مخدرات -تهريب املخدرات -إقرار مصدق شرع ا -املشاركة يف جلب املخدرات من اخلارج -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليهم -التعزير بالسجن واجللد وغرامة مالية ومصادرة اجلوال وإلغاء الشريحة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3452825 :‬تاريخه‪1434/3/2 :‬هـ‬\n                  ‫رقم الدعوى‪3417873 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪34245929‬تاريخه‪1434/6/19 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تهريــب املخــدرات ‪ -‬إقــرار مصــدق شــرع ًا ‪ -‬املشــاركة يف‬\n‫جلــب املخــدرات مــن اخلــارج ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬ثبــوت‬\n‫إدانــة املدعــى عليهــم ‪ -‬التعزيــر بالســجن واجللــد وغرامــة ماليــة‬\n                                ‫ومصــادرة اجلــوال وإلغــاء الشــريحة‪.‬‬\n\n\n\n\n                ‫‪ -‬قوله تعالى‪( :‬وال تفسدوا يف األرض بعد إصالحها)‪.‬‬\n                                 ‫‪ -‬وقوله تعالى‪( :‬واهلل ال يحب الفساد)‪.‬‬\n‫‪ -‬املــادة الســابعة والثالثــون‪ ،‬والثالثــة واخلمســون‪ ،‬والسادســة‬\n‫واخلمســون‪ ،‬والثامنــة واخلمســون‪ ،‬والتاســعة واخلمســون‪ ،‬والســتون‬\n                 ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪ -‬مــا جــاء يف تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم‬\n                             ‫(‪9798/4/5/1‬س) يف ‪1428/2/10-9‬هــ‪.‬‬\n\n\n\n\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه األول باملشــاركة‬\n‫عــن طريــق االتفــاق واملســاعدة يف تهريــب كميــة قدرهــا ســتة وعشــرون‬\n‫بالطــة مــن احلشــيش املخــدر بلــغ وزنهــا خمســة وعشــرين كيلــو وثمامنائة‬\n‫جــرام‪ ،‬وللمدعــى عليــه الثانــي بتهريــب ثــاث عشــرة بالطة من احلشــيش‬\n\n                                                                                ‫‪56‬‬\n\f     ‫املخــدر إلــى داخــل األراضــي الســعودية بلــغ وزنهــا‪ ،‬اثنــا عشــر كيلــو و‬\n     ‫تســعمائة جــرام‪ ،‬وللمدعــى عليــه الثالــث بتهريــب ثــاث عشــرة بالطــة‬\n     ‫مــن احلشــيش املخــدر إلــى داخــل األراضــي الســعودية بلــغ وزنهــا اثنــا‬\n     ‫عشــر كيلــو وتســعمائة جــرام ‪ -‬طلــب املدعــي العــام إثبــات إدانتهــم مبــا‬\n     ‫أســند إليهــم واحلكــم بقتلهــم تعزيــراً‪ ،‬ومصــادرة جهــاز اجلــوال املضبــوط‬\n     ‫مــع املدعــى عليــه األول وفــق نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة‪ ،‬وإلغــاء الشــريحة‪ ،‬وعــدم صرفهــا ملــن أســاء اســتخدامها‬\n     ‫الســتخدامها يف جرميــة التهريــب ‪ ،‬بعــرض دعــوى املدعــي العــام علــى‬\n     ‫املدعــى عليهــم أجــاب املدعــى عليــه األول باملصادقــة‪ ،‬كمــا أجــاب‬\n     ‫كل واحــد مــن املدعــى عليهمــا الثانــي والثالــث باملصادقــة علــى تهريــب‬\n     ‫الكميــة املذكــورة‪ ،‬ودفــع أنــه ال يعلــم أنهــا مــن احلشــيش املخــدر‪ ،‬و‬\n     ‫أنــه كان يظــن أنهــا شــمة‪ -‬جــرى االطــاع علــى إقــرارات املدعــى عليهــم‬\n     ‫حتقيق ـ ًا واملصدقــة شــرعاً‪ ،‬وبعرضهــا عليهــم صادقــوا عليهــا جميعــا‪،‬‬\n     ‫وقــرروا توبتهــم وندمهــم ‪ ،‬تبــن عــدم وجــود ســوابق للمدعــى عليهــم‬\n     ‫‪ -‬ونظــر ًا إلقــرار املدعــى عليــه األول يف مجلــس احلكــم وحتقيق ـاً‪،‬‬\n     ‫املصــدق شــرع ًا باملشــاركة عــن طريــق االتفــاق واملســاعدة يف تهريــب‬\n     ‫كميــة مــن احلشــيش املخــدر واملذكــورة يف دعــوى املدعــي العــام إلــى‬\n     ‫داخــل األراضــي الســعودية مقابــل مبلــغ مالــي‪ ،‬وإلقــرار كل واحــد‬\n     ‫مــن املدعــى عليهمــا الثانــي والثالــث يف مجلــس احلكــم وحتقيق ـاً‪،‬‬\n     ‫املصــدق شــرع ًا بتهريــب كل واحــد منهــم كميــة مــن احلشــيش املخــدر‬\n     ‫واملذكــورة يف دعــوى املدعــي العــام إلــى داخــل األراضــي الســعودية‬\n     ‫مقابــل مبلــغ مالــي‪ ،‬وألن مــا نســب إلــى املدعــى عليهــم فعــل محــرم‪،‬‬\n     ‫ومعاقــب عليــه‪ ،‬وألن التعزيـ َـر بالقتـ ِـل جائ ـ ٌز وليــس بواجـ ٍـب‪ ،‬ونظــر ًا‬\n\n\n‫‪57‬‬\n\f‫إليجابيــة العينــة التــي اتهــم املدعــى عليهــم بتهريبهــا واملشــاركة يف ذلــك‬\n‫باحتوائهــا املــواد احملظــورة كمــا جــاء يف التقريــر الكيميائــي الشــرعي‬\n‫يف دعــوى املدعــي العــام‪ ،‬وألهليــة كل واحــد مــن املدعــى عليهــم‪ ،‬وملــا‬\n‫ظهــر مــن صــدق توبــة املدعــى عليهــم‪ ،‬وإظهارهــم النــدم علــى مــا بــدر‬\n‫منهــم‪ ،‬واعترافهــم وإقرارهــم بفعلهــم قرينــة قويــة علــى ذلــك‪ ،‬فقــد ثبتــت‬\n‫إدانــة املدعــى عليــه األول باملشــاركة عــن طريــق االتفــاق واملســاعدة يف‬\n‫تهريــب كميــة مــن احلشــيش املخــدر إلــى اململكــة العربيــة الســعودية‬\n‫واملذكــورة يف دعــوى املدعــي العــام بقصــد الكســب املــادي‪ ،‬وإدانــة‬\n‫املدعــى عليهمــا الثانــي والثالــث بتهريــب كل واحــد منهمــا كميــة مــن‬\n‫احلشــيش املخــدر إلــى اململكــة العربيــة الســعودية واملذكــورة يف دعــوى‬\n‫املدعــي العــام بقصــد الكســب املــادي‪ ،‬ومت احلكــم بــرد طلــب املدعــي‬\n‫العــام قتــل املدعــى عليهــم األول والثانــي والثالــث تعزيــراً‪ ،‬واحلكــم‬\n‫بتعزيــر كل واحــد مــن املدعــى عليهــم األول والثانــي والثالــث بســجن‬\n‫كل واحــد منهــم اثنتــي عشــرة ســنة ‪ ،‬وبجلــد كل واحــد منهــم ألــف‬\n‫ومائتــي جلــدة‪ ،‬مفرقــة علــى دفعــات‪ ،‬وتغــرمي كل واحــد منهــم مبلغ ـ ًا‬\n‫قــدره مائــة ألــف ريــال ســعودي‪ ،‬وإبعــاد املدعــى عليهــم األول والثانــي‬\n‫والثالــث عــن اململكــة العربيــة الســعودية‪ ،‬بعــد قضــاء محكومياتهــم‪،‬‬\n‫وأال يســمح لهــم بدخــول اململكــة العربيــة الســعودية إال وفــق مــا تقضــي‬\n‫بــه تعليمــات احلــج والعمــرة‪ ،‬ومصــادرة جهــاز اجلوال املضبــوط مع املدعى‬\n‫عليــه األول‪ ،‬وإلغــاء الشــريحة ذات الرقــم‪ ،‬وعــدم صرفهــا ملــن أســاء‬\n‫اســتخدامها‪ ،‬بعــرض احلكــم علــى املدعــي العــام واملدعــى عليهــم قــرر‬\n‫املدعــي العــام عــدم قناعتــه باحلكــم‪ ،‬وطلــب اســتئناف احلكــم بالئحــة‬\n‫اعتراضيــة‪ ،‬كمــا قــرر كل واحــد مــن املدعــى عليهــم األول والثانــي‬\n\n\n                                                                                     ‫‪58‬‬\n\f     ‫والثالــث قناعتــه باحلكــم‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                               ‫املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلدينــا نحــن ‪ ، ......‬و‪ ، ......‬و‪ ......‬القضــاة يف‬\n     ‫احملكمــة العامــة بنجــران‪ ،‬حضــر املدعــي العــام ‪ ......‬واملكلــف بتمثيــل‬\n     ‫اإلدعــاء العــام (مدعــي عــام) لــدى احملكمــة العامــة بنجــران‪ ،‬وذلــك‬\n     ‫مبوجــب خطــاب ســعادة رئيــس فــرع هيئــة التحقيــق واإلدعــاء العــام‬\n     ‫ينجــران رقــم‪ ......‬يف ‪1433/8/20‬ه ـ وحضــر حلضــوره‪ :‬املدعــى عليــه‬\n     ‫األول‪ ......‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪ ......‬واملدعــى‬\n     ‫عليــه الثانــي‪ ...... :‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪، ......‬‬\n     ‫واملدعــى عليــه الثالــث‪ ...... :‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقــم‬\n     ‫‪ ......‬وقــد ادعــى املدعــي العــام عليهــم بالئحــة الدعــوى العامــة التــي جــاء‬\n     ‫فيهــا‪( :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة‬\n     ‫جنــران أدعــي علــى املذكوريــن أعــاه بأنــه قــد ورد مبحضــر القبــض‬\n     ‫املعــد مــن حــرس احلــدود قطــاع ســقام رقــم (‪ )01359‬وبتاريــخ‬\n     ‫‪1433/11/12‬هـ أنه يف الســاعة (‪ )3:00‬رصد النظام احلراري احملمول‬\n     ‫التابــع للفصيــل األول املتمركــز يف املــكان املســمى (‪ ) ......‬ثالثــة‬\n     ‫أشــخاص قادمــن مــن اجلنــوب إلــى الشــمال يحاولــون الدخول إلــى البالد‬\n     ‫بطريقــة غيــر مشــروعة ســيرا علــى األقــدام مــن املــكان املســمى (‪) ......‬‬\n     ‫‪ ،‬ومت اعتراضهــم مــن قبــل الكمــن وإطــاق النــار عليهــم ‪ ،‬وأتضــح‬\n     ‫أنهــم املتهمــن أعــاه وبتفتيشــهم عثــر بحوزتهــم علــى عــدد (‪ )26‬ســت‬\n     ‫وعشــرين بالطــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)25.800‬كجــم‬\n\n‫‪59‬‬\n\f‫خمســة وعشــرين كيلــو وثمامنائــة جــرام وبالتحقيــق املبدئــي معهــم‬\n‫أتضــح أن هنــاك شــخص ســعودي يســتقبلهم بالداخــل فتــم متكــن أحــد‬\n‫املهربــن مــن االتصــال علــى املســتقبل هاتفيــا ويف الســاعة (‪ )4:30‬مــن‬\n‫نفــس اليــوم مت مالحظــة قــدوم ســيارة مــن نــوع ‪ .....‬يســتقلها شــخصان‬\n‫إلــى املوقــع وعنــد اعتراضهــا بــادر بإطــاق النــار باجتــاه الدوريــات فــردوا‬\n‫باملثــل ومتكــن املســتقبالن مــن الفــرار ودخــول حــي ســكني ومت‬\n‫محاصــرة املنــزل الــذي دخلــت فيــه الســيارة حتــى ســمح صاحــب املنــزل‬\n‫بالدخــول وهــو املدعــو ‪ ...... /‬ومت حجــز الســيارة وبهــا أثــار طلقــات‬\n‫بالعجلتــن األماميــة اليســرى واالحتيــاط‪ ،‬وعنــد تفتيشــها عثــر بالداخــل‬\n‫علــى مبلــغ مالــي قــدره (‪ )4000‬أربعــة آالف ريــال ســعودي ‪ ،‬وهــي مــن‬\n‫نــوع ‪ ....‬صنــع (‪ )2013‬عائــدة ملكيتهــا إلــى املدعــو ‪ ...... /‬ســعودي‬\n‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ) ......‬ونســخة مــن ورقــة تامــن‬\n‫للوحــة رقــم (‪ -1 .) ......‬مت إيقافهــم وإيداعهــم شــعبة الســجن العــام‬\n‫بنجــران اســتنا ًدا للقــرار الــوزاري (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي‬\n‫علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪-2 .‬مت مخاطبــة حــرس‬\n‫احلــدود بنجــران بشــأن مــا صــدر بحقهــم مــن أحــكام إداريــة لقــاء‬\n‫مخالفتهــم لنظــام أمــن احلــدود مبوجــب اخلطــاب رقــم (‪ ) ......‬وتاريــخ‬\n‫‪1433/11/17‬هــ‪ -3 .‬مت فــرز أوراق للبحــث عــن مالــك الســيارة و قيــدت‬\n‫لدينــا بالقيــد رقــم (‪ ) ......‬و تاريــخ ‪1433/11/24‬هــ‪ .‬و بســماع أقــوال‬\n‫املتهمــن أفــادوا بأنهــم تقابلــوا يف اليمــن يف املــكان املســمى (‪ ) ......‬مــع‬\n‫املدعــو‪ ...... /‬و يرافقــه املدعــو‪ ...... /‬و أتفــق معهــم علــى إدخــال املهربــات‬\n‫مــن مــادة احلشــيش املخــدر إلــى الســعودية مبقابــل (‪ )800‬ثمامنائــة ريــال‬\n‫ســعودي لــكل بالطــة علــى أن يحمــل كل مــن املتهــم الثانــي و الثالــث‬\n\n\n                                                                                        ‫‪60‬‬\n\f     ‫(‪ )13‬ثــاث عشــرة بالطــة لــكل واحــد منهــم و املتهــم األول يقــوم‬\n     ‫مبســاعدتهم و املســح أمامهــم ‪ ،‬ثــم ركبــوا يف ســيارة مــن نــوع ‪ .....‬إلــى‬\n     ‫قــرب احلــدود و واصلــوا الســير ســيرا علــى األقــدام و عنــد وصولهــم إلــى‬\n     ‫أعلــى اجلبــل توقــف املدعــو ‪ ...... /‬وقــام بإعطــاء املتهــم األول جهــاز جــوال‬\n     ‫بــه شــريحة ســعودية رقــم (‪ ) ......‬وأبلغــه مبواصلــة الســير والتنســيق مــع‬\n     ‫املســتقبل علــى الرقــم (‪ ) ......‬و قبــل وصولهــم إلــى الشــبك مت القبــض‬\n     ‫عليهــم ‪ ،‬و أفــادوا بأنهــم ال يعرفــون املســتقبل و أن هدفهــم مــن العمليــة‬\n     ‫هــو الكســب املــادي ‪ .‬و باســتجواب املتهــم األول ‪ ...... /‬قيامــه باالتفــاق‬\n     ‫و املســاعدة يف تهريــب أحمــال رفاقــه و قدرهــا (‪ )26‬ســت و عشــرين‬\n     ‫بالطــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)25.800‬كجــم خمســة و‬\n     ‫عشــرين كيلــو و ثمامنائــة جــرام ‪ ،‬مبقابــل مبلــغ (‪ )800‬ثمامنائــة ريــال‬\n     ‫ســعودي لــكل بالطــة تــوزع بينهــم بالتســاوي‪ ،‬و ذكــر أن صاحــب‬\n     ‫احلملــة همــا املدعــوان ‪ ....../‬و ‪ ، ......‬و أمــا املســتقبل فــا يعرفــه و ذكــر‬\n     ‫أنــه كان معهــم املدعــو ‪ ...... /‬و هــو املســاح ‪ ،‬و عنــد وصولهــم إلــى رأس‬\n     ‫اجلبــل طلــب مــن املتهــم األول املســح و التنســيق مــع صاحــب احلملــة و‬\n     ‫املســتقبل إلــى أن يصلــوا إلــى الشــبك ‪ ،‬و أفــاد بــأن اجلــوال املوجــود معــه‬\n     ‫و بــه شــريحة ســعودية فقــد أســتخدمه يف العمليــة وهــو عائــد إلــى املدعــو‬\n     ‫‪ ، ......‬وأن الغــرض مــن ذلــك الكســب املــادي ‪ ،‬وصــادق علــى إقــراره‬\n     ‫شــرعا‪.‬و باســتجواب املتهــم الثانــي ‪ ...... /‬أقــر بقيامــه بتهريــب عــدد (‪)13‬‬\n     ‫ثــاث عشــرة بالطــة مــن احلشــيش‪ ،‬مبقابــل مبلــغ (‪ )800‬ثمامنائــة ريــال‬\n     ‫ســعودي لــكل بالطــة ‪ ،‬و صاحــب احلملــة هــو املدعــو‪ ، ...... /‬والغــرض‬\n     ‫مــن ذلــك الكســب املــادي‪ ،‬صــادق علــى إقــراره شــرعا‪ .‬و باســتجواب‬\n     ‫املتهــم الثالــث ‪ ...... /‬أقــر بقيامــه بتهريــب عــدد (‪ )13‬ثــاث عشــرة بالطة‬\n\n\n‫‪61‬‬\n\f‫مــن احلشــيش‪ ،‬مبقابــل مبلــغ (‪ )800‬ثمامنائــة ريــال ســعودي لــكل بالطــة‬\n‫‪ ،‬و صاحــب احلملــة هــو املدعــو‪ ، ...... /‬و الغــرض مــن ذلــك الكســب‬\n‫املــادي‪ ،‬و صــادق علــى إقــراره شــرعا‪ .‬وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪ ) ......‬الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n‫الطبيــة الشــرعية مبنطقــة مكــة املكرمــة أن العينتــن (أ ‪ ،‬ب) املرســلة‬\n‫للتحليــل باحلــرز الســري رقــم (‪ )539‬ثبــت أنهــا حشــيش مخــدر وحتتــوي‬\n‫علــى املــادة الفعالــة للحشــيش املخــدر واحلشــيش املخــدر مــن املــواد‬\n‫املدرجــة بجــداول املخــدرات واملؤثــرات العقليــة (‪1‬فئــة أ) امللحقــة بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫لــكل مــن األول‪ ......‬باملشــاركة عــن طريــق االتفــاق و املســاعدة يف‬\n‫تهريــب كامــل الكميــة و قدرهــا (‪ )26‬ســتة و عشــرين بالطــة مــن‬\n‫احلشــيش املخــدر بلــغ وزنهــا (‪25,800‬كجم)خمســة وعشــرين كيلــو‬\n‫وثمامنائــة جــرام‪ .‬والثانــي ‪ : ...... /‬بتهريــب (‪ )13‬ثــاث عشــرة بالطــة مــن‬\n‫احلشــيش املخــدر إلــى داخــل األراضــي الســعودية بلــغ وزنهــا (‪)12,900‬‬\n‫أثنــى عشــر كيلــو و تســعمائة جــرام‪ .‬والثالــث ‪ ...... /‬بتهريــب (‪ )13‬ثالث‬\n‫عشــرة بالطــة مــن احلشــيش املخــدر إلــى داخــل األراضــي الســعودية بلــغ‬\n‫ا‬\n‫وزنهــا (‪ )12,900‬أثنــى عشــر كيلــو وتســعمائة جــرام ‪ ،‬ممــا يعــد فع ـ ً‬\n‫مجرمـ ًا اســتناد ًا للفقــرة األولــى و السادســة مــن املــادة الثالثــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪-1 :‬‬\n‫إقراراتهــم املصدقــة شــرع ًا املنــوه عنــه واملدونــة عــل دفتــر التحقيــق رقــم‬\n‫(‪ )2‬املرفــق لفــه (‪ ، )45‬واعترافهــم لــدى جهــة الضبــط املنــوه عنــه‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫واملرفــق علــى اللفــات مــن ( ‪22‬حتى ‪-2 .)25‬محضري القبض والتفتيش‬\n     ‫املنــوه عنهــا واملرفقــة علــى اللفــات (‪ 1‬حتــى ‪ -3 . )4‬مــا تضمنــه التقريــر‬\n     ‫الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪ . )47‬وحيــث أن مــا‬\n     ‫أقــدم عليــه املتهمــون وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم‬\n     ‫شــرع ًا ومعاقــب عليــه نظامـ ًا وفقـ ًا لنظام مكافحة املخــدرات واملؤثرات‬\n     ‫العقليــة يف عقوباتــه األصليــة والتكميليــة‪ ،‬لــذا أطلــب إثبــات إدانتهــم‬\n     ‫مبــا أســند إليهــم واحلكــم عليهــم باآلتــي ‪-1 :‬قتــل املتهــم األول تعزيــر ًا‬\n     ‫اســتنادا للفقــرة الرابعــة مــن البنــد (أوال) مــن املــادة (‪ )37‬الســابعة و‬\n     ‫الثالثــن و املــادة (‪ )58‬الثامنــة و اخلمســن مــن ذات النظــام وقتــل املتهمان‬\n     ‫الثانــي و الثالــث تعزيــر ًا اســتناد ًا للفقــرة (‪ )1‬مــن البنــد (أوالً) مــن املــادة‬\n     ‫(‪ )37‬الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة املنــوه عنــه‪ -2 .‬مصــادرة جهــاز اجلــوال املضبــوط مــع املتهــم األول‬\n     ‫مــن نــوع ‪ ....‬يحمــل الرقــم املصنعــي ‪ ......‬اســتناد ًا للفقــرة األولــى مــن‬\n     ‫املــادة (‪ )53‬الثالثــة واخلمســن مــن نظــام املخــدرات املنــوه عنــه ‪ ،‬و إلغــاء‬\n     ‫الشــريحة ذات الرقــم التسلســلي ‪ ......‬وعــدم صرفهــا ملــن أســاء‬\n     ‫اســتخدامها اســتنادا لتعميــم صاحــب الســمو امللكــي وزيــر الداخليــة‬\n     ‫رقــم (‪9798/4/5/1‬س) يف ‪1428/2/10-9‬ه ـ الســتخدامها يف جرميــة‬\n     ‫التهريــب ‪ .‬وبــاهلل التوفيــق)‪ .‬هكــذا ادعــى‪ .‬وبعــرض دعــوى املدعــي العام‬\n     ‫علــى املدعــى عليهــم بعــد التحقــق مــن هوياتهــم أجــاب املدعــى عليه األول‬\n     ‫قائ ـاً‪ :‬إن مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن أننــي قمــت‬\n     ‫باملشــاركة عــن طريــق االتفــاق واملســاعدة يف تهريــب كميــة احلشــيش‬\n     ‫املخــدر واملذكــورة يف دعــوى املدعــي العــام فهــذا كلــه صحيــح‪ ،‬وأنــا‬\n     ‫قمــت بحمــل الطعــام للمهربــن مــن اليمــن‪ ،‬وأمــا مســح الطريــق فلــم‬\n\n\n‫‪63‬‬\n\f‫أمســح الطريــق أبداً‪،‬وإمنــا كلفنــي صاحــب احلملــة بحمــل الطعــام‬\n‫واملشــي مــع املهربــن (املدعــى عليهمــا الثانــي والثالــث) فقمــت بذلــك‪،‬‬\n‫ومشــينا حتــى مت القبــض علينــا‪ ،‬ومــا ذكــره املدعــي العــام مــن أنــه عثــر‬\n‫بحوزتــي علــى جــوال بــه شــريحة ســعودية وقــد قــام صاحــب احلملــة‬\n‫بتســليمي هــذا اجلــوال مــن أجــل التواصــل مــع املســتقبل بعــد الوصــول‬\n‫إلــى الســعودية‪ .‬هكــذا أجــاب‪ .‬كمــا أجــاب كل واحــد مــن املدعــى‬\n‫عليهمــا الثانــي والثالــث منفــرد ًا بقولــه‪ :‬إن مــا ذكــره املدعــي العــام يف‬\n‫دعــواه ضــدي مــن أنــه قبــض علــي يف املــكان والزمــان اللذيــن ذكرهمــا‬\n‫املدعــي العــام‪ ،‬وأننــي قمــت بتهريــب كميــة مــن احلشــيش املخــدر‬\n‫واملذكــورة يف دعــوى املدعــي العــام فهــذا كلــه صحيــح‪ ،‬ولكنــي لــم‬\n‫أكــن أعلــم بــأن هــذه الكميــة التــي قمــت بتهريبهــا أنهــا مــن احلشــيش‬\n‫املخــدر فقــد كنــت أظنهــا شــمه‪ ،‬ولــم أعلــم أنهــا حشــيش إال بعــد‬\n‫القبــض علــي‪ .‬هكــذا أجــاب كل واحــد منهــم منفــردا‪ .‬وقــد جــرى منــا‬\n‫اإلطــاع علــى أوراق املعاملــة‪ ،‬فوجدنــا إقــرار املدعــى عليــه األول ‪......‬‬\n‫حتقيق ـ ًا واملصــدق شــرع ًا مــن احملكمــة العامــة بنجــران واملــدون علــى‬\n‫الصفحــة رقــم (‪ )3‬مــن دفتــر احلقيــق رقــم (‪ )2‬املرفــق لفــة رقــم (‪)45‬‬\n‫ونصــه (أقــر أنــا ‪ ، ...... /‬مينــي اجلنســية مبوجــب البطاقــة البديلــة رقم‪......‬‬\n‫صــادره مــن حــرس احلــدود ســقام بتاريــخ ‪1433/11/12‬ه ـ ‪ ،‬وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرع ًا بأنــه يف يــوم ‪1433/11/12‬ه ـ‬\n‫قبــض علــي مــن قبــل حــرس احلــدود كمــا جــاء يف محضــر القبــض رقــم‬\n‫(‪ ) ......‬وتاريــخ ‪1433/11/12‬ه ـ ‪ ،‬وكان دوري منســق مــع املســتقبل‬\n‫وصاحــب احلملــة وأحمــل الــزاد ‪ ،‬وأن القصــد مــن ذلــك الكســب املــادي‬\n‫‪ ،‬وأنــي أعلــم أن تهريــب املخــدرات للســعودية محــرم ومجــرم وليــس لــدي‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫أي ســوابق مخــدرات وأن اجلــوال املوجــود بحوزتــي والــذي اتصلــت بــه‬\n     ‫علــى املســتقبل يعــود إلــى املدعــو ‪ ......‬وكان دوره مســاح وهــو الــذي قــام‬\n     ‫بنقلنــا إلــى رأس اجلبــل بســيارته‪ .‬املقــر مبــا فيــه ‪ ...... /‬إبهامــه) وبعرضــه‬\n     ‫عليــه أجــاب قائ ـاً‪ :‬إن إقــراري هــذا صحيــح‪ ،‬وقــد تبــت إلــى اهلل عــز‬\n     ‫وجــل مــن هــذه اجلرميــة‪ ،‬وأنــا نــادم علــى مــا اقترفتــه‪ .‬كمــا جــرى االطالع‬\n     ‫علــى إقــرار املدعــى عليــه الثانــي ‪ ......‬حتقيق ـ ًا واملصــدق شــرع ًا مــن‬\n     ‫احملكمــة العامــة بنجــران املــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر‬\n     ‫احلقيــق رقــم (‪ )2‬املرفــق لفــة رقــم (‪ )45‬ونصــه (أقــر أنــا ‪ ، ...... /‬مينــي‬\n     ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪ ......‬بتاريــخ ‪1433/11/12‬ه ـ‬\n     ‫صــادره مــن حــرس احلــدود قطــاع ســقام‪ ،‬وأنــا بكامــل قــواي العقليــة‬\n     ‫املعتبــرة شــرع ًا ونظام ـ ًا بأنــه يف يــوم ‪1433/11/12‬ه ـ قبــض علــي مــن‬\n     ‫قبــل حــرس احلــدود كمــا جــاء يف احملضــر القبــض رقــم (‪ ) ......‬بتاريــخ‬\n     ‫‪1433/11/12‬ه ـ ‪ ،‬وكنــت أحمــل حمــل عبــارة عــن (‪ )13‬ثــاث عشــرة‬\n     ‫بالطــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪12.900‬كجــم) اثنــي عشــر‬\n     ‫كيلــو وتســعمائة جــرام وأن القصــد مــن ذلــك الكســب املــادي وأنــي‬\n     ‫أعلــم أن تهريــب املخــدرات للســعودية محــرم وليــس لــدي أي ســوابق‬\n     ‫مخــدرات‪ ).‬املقــر مبــا فيــه ‪ ...... /‬إبهامــه) وبعرضــه عليــه أجــاب قائ ـاً‪:‬‬\n     ‫إن إقــراري هــذا صحيــح‪ ،‬وقــد تبــت إلــى اهلل عــز وجــل مــن هــذه اجلرميــة‪،‬‬\n     ‫وأنــا نــادم علــى مــا اقترفتــه‪ .‬كمــا جــرى االطــاع علــى إقــرار املدعــى‬\n     ‫عليــه الثالــث‪ ...... ...... :‬حتقيقـ ًا واملصــدق شــرع ًا مــن احملكمــة العامــة‬\n     ‫بنجــران املــدون علــى الصفحــة رقــم (‪ )2‬مــن دفتــر احلقيق رقــم (‪ )2‬املرفق‬\n     ‫لفــة رقــم ‪ ......‬ونصــه (أقــر أنــا ‪ ، ...... /‬مينــي اجلنســية مبوجــب البطاقــة‬\n     ‫البديلــة رقــم ‪ ......‬بتاريــخ ‪1433/11/12‬ه ـ صــادره مــن حــرس احلــدود‬\n\n\n‫‪65‬‬\n\f‫قطــاع ســقام‪ ،‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا ونظامـ ًا بأنــه‬\n‫يف يــوم ‪1433/11/12‬ه ـ قبــض علــي مــن قبــل حــرس احلــدود كمــا جــاء‬\n‫يف احملضــر القبــض رقــم (‪ ) ......‬بتاريــخ ‪1433/11/12‬ه ـ ‪ ،‬وكنــت‬\n‫أحمــل حمــل عبــارة عــن (‪ )13‬ثــاث عشــرة بالطــة مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪12.900‬كجــم) اثنــي عشــر كيلــو وتســعمائة جــرام وأن‬\n‫القصــد مــن ذلــك الكســب املــادي وأنــي أعلــم أن تهريــب املخــدرات‬\n‫للســعودية محــرم وليــس لــدي أي ســوابق مخــدرات‪ ).‬املقــر مبــا فيــه ‪/‬‬\n‫‪ ......‬إبهامــه) وبعرضــه عليــه أجــاب قائ ـاً‪ :‬إن إقــراري هــذا صحيــح‪،‬‬\n‫وقــد تبــت إلــى اهلل عــز وجــل مــن هــذه اجلرميــة‪ ،‬وأنــا نــادم علــى مــا‬\n‫اقترفتــه‪ .‬كمــا جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي‬\n‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n‫مبنطقــة مكــة املكرمــة رقــم ‪ ......‬وتاريــخ ‪1433/11/28‬ه ـ املرفــق‬\n‫علــى اللفــة رقــم ‪ 55‬واملتضمــن أن العينــة املرســلة ثبــت أنهــا حشــيش‬\n‫مخــدر وحتتــوي علــى املــادة الفعالــة للحشــيش املخــدر مــن املــواد املدرجــة‬\n‫بجــداول املــواد املخــدرة واملؤثــرات العقليــة املرفقــة بالتعميــم البرقــي‬\n‫لصاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )19/89400‬يف‬\n‫‪1426/10/25‬ه ـ والصــادر باملرســوم امللكــي رقــم (م‪ )39/‬يف‬\n‫‪1426/7/8‬ه ـ أ‪.‬هــ‪ .‬كمــا جــرى االطــاع علــى صفحــة ســوابق املدعــى‬\n‫عليهــم املرفقــة لفــة رقــم (‪ )54‬واملتضمنــة عــدم وجــود ســوابق علــى‬\n‫املدعــى عليهــم‪ .‬أ‪.‬ه‪ .‬كمــا جــرى االطــاع علــى صــورة محضــر القبــض‬\n‫املرفقــة علــى اللفــات رقــم (‪ )3-1‬وكــذا محضــر التفتيــش املرفــق علــى‬\n‫اللفــة رقــم (‪ )4‬فوجدناهمــا مطابقــن ملــا جــاء يف دعــوى املدعــي العــام‪.‬‬\n‫وبســؤال املدعــي العــام واملدعــى عليهــم هــل لــدى أحــد منهــم مــا يــود‬\n\n\n                                                                                      ‫‪66‬‬\n\f     ‫إضافتــه علــى مــا ســبق رصــده؟ فأجــاب كل واحــد منهــم مبفــرده قائـاً‪:‬‬\n     ‫ـدي ســوى مــا قدمــت هكــذا قــرر كل واحــد منهــم منفــرداً‪.‬‬           ‫إنــه ليــس لـ َّ‬\n     ‫فعليــه‪ ،‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وإلقــرار املدعــى‬\n     ‫عليــه األول يف مجلــس احلكــم‪ ،‬وحتقيق ـ ًا املصــدق شــرع ًا باملشــاركة‬\n     ‫عــن طريــق االتفــاق واملســاعدة يف تهريــب كميــة مــن احلشــيش املخــدر‬\n     ‫واملذكــورة يف دعــوى املدعــي العــام إلــى داخــل األراضــي الســعودية‬\n     ‫مقابــل مبلــغ مالــي‪ ،‬وإلقــرار كل واحــد مــن املدعــى عليهمــا الثانــي‬\n     ‫والثالــث يف مجلــس احلكــم‪ ،‬وحتقيق ـ ًا املصــدق شــرع ًا بتهريــب كل‬\n     ‫واحــد منهــم كميــة مــن احلشــيش املخــدر واملذكــورة يف دعــوى املدعــي‬\n     ‫العــام إلــى داخــل األراضــي الســعودية مقابــل مبلــغ مالــي‪ ،‬ولكــون‬\n     ‫املخــدرات مــن أشــد املفســدات فتــك ًا باملجتمعــات وهــي تفســد العقــل‬\n     ‫والديــن وتفتــك باألمــة وتهلكهــا معنوي ـ ًا واقتصادي ـ ًا قــال ســبحانه (وال‬\n     ‫تفســدوا يف األرض بعــد إصالحهــا) وقــال عــز مــن قائــل (واهلل ال يحــب‬\n     ‫الفســاد) وألن مــا نســب إلــى املدعــى عليهــم فعــل محــرم‪ ،‬ومعاقــب عليه‪،‬‬\n     ‫وفيــه ضــرر علــى العبــاد والبــاد‪ ،‬وألنــه يحتــاط يف الدمــاء مــا ال يحتــاط‬\n     ‫يف غيرهــا‪ ،‬وألن التعزيـ َـر بالقتـ ِـل جائـ ٌز وليــس بواجـ ٍـب‪ ،‬ونظــر ًا إليجابيــة‬\n     ‫العينــة التــي اتهــم املدعــى عليهــم بتهريبها واملشــاركة يف ذلــك باحتوائها‬\n     ‫املــواد احملظــورة كمــا جــاء يف التقريــر الكيميائــي الشــرعي املشــار‬\n     ‫إليــه يف دعــوى املدعــي العــام‪ ،‬وألهليــة كل واحــد مــن املدعــى عليهــم‪،‬‬\n     ‫وملــا ظهــر لنــا مــن صــدق توبــة املدعــى عليهــم‪ ،‬وإظهارهــم النــدم علــى مــا‬\n     ‫بــدر منهــم‪ ،‬واعترافهــم وإقرارهــم بفعلهــم قرينــة قويــة علــى ذلــك‪ ،‬وملــا‬\n     ‫جــاء يف البنــد ثاني ـ ًا مــن املــادة الســابعة والثالثــن وملــا جــاء يف املــواد‬\n     ‫الثالثــة واخلمســن‪ ،‬والسادســة واخلمســن‪ ،‬والثامنــة واخلمســن‪،‬‬\n\n\n‫‪67‬‬\n\f‫والتاســعة واخلمســن‪ ،‬والســتني مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ ،‬ومــا جــاء يف تعميــم صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم (‪9798/4/5/1‬س) يف ‪1428/2/10-9‬هــ‪ ،‬وجلميــع مــا‬\n‫تقــدم فقــد حكمنــا إجماع ـ ًا مبــا يلــي‪ :‬أوالً‪ :‬إدانــة املدعــى عليــه األول‬\n‫باملشــاركة عــن طريــق االتفــاق واملســاعدة يف تهريــب كميــة مــن‬\n‫احلشــيش املخــدر إلــى اململكــة العربيــة الســعودية واملذكــورة يف دعــوى‬\n‫املدعــي العــام بقصــد الكســب املــادي‪ ،‬وإدانــة املدعــى عليهمــا الثانــي‬\n‫والثالــث بتهريــب كل واحــد منهمــا كميــة مــن احلشــيش املخــدر إلــى‬\n‫اململكــة العربيــة الســعودية واملذكــورة يف دعــوى املدعــي العــام بقصــد‬\n‫الكســب املــادي‪ .‬ثانيـاً‪ :‬رد طلــب املدعــي العــام قتــل املدعــى عليهــم األول‬\n‫والثانــي والثالــث تعزيــراً‪ .‬ثالث ـاً‪ :‬تعزيــر كل واحــد مــن املدعــى عليهــم‬\n‫األول والثانــي والثالــث بســجن كل واحــد منهــم اثنتــي عشــرة ســنة‬\n‫ابتــداء مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‪ ،‬وبجلــد كل واحــد‬\n‫منهــم ألــف ومائتــي جلــدة‪ ،‬مفرقــة علــى دفعــات‪ ،‬كل دفعــة خمســون‬\n‫جلــدة‪ ،‬بــن كل دفعــة والتــي تليهــا ثالثــون يوم ـاً‪ ،‬وتغــرمي كل واحــد‬\n‫منهــم مبلغـ ًا قــدره مائــة ألــف ريــال ســعودي‪ .‬رابعـاً‪ :‬إبعــاد املدعــى عليهــم‬\n‫األول والثانــي والثالــث عــن اململكــة العربيــة الســعودية‪ ،‬بعــد قضــاء‬\n‫محكومياتهــم واســتيفاء مالهــم ومــا عليهــم مــن حقــوق لــدى غيرهــم‪،‬‬\n‫وأال يســمح لهــم بدخــول اململكــة العربيــة الســعودية إال وفــق مــا تقضــي‬\n‫بــه تعليمــات احلــج والعمــرة‪ .‬خامسـاً‪ :‬مصــادرة جهــاز اجلــوال املضبــوط مــع‬\n‫املتهــم األول مــن نــوع ‪ .....‬ويحمــل الرقــم املصنعــي ‪ ......‬وإلغــاء الشــريحة‬\n‫ذات الرقــم التسلســلي (‪ ) ......‬وعــدم صرفهــا ملــن أســاء اســتخدامها‪.‬‬\n‫وقررنــا تنظيــم قــرار شــرعي بذلــك‪ ،‬وبإعــان احلكــم‪ ،‬وعرضــه علــى‬\n\n\n                                                                                        ‫‪68‬‬\n\f     ‫املدعــى العــام واملدعــى عليهــم قــرر املدعــي العــام عــدم قناعتــه باحلكم‪،‬‬\n     ‫وطلــب اســتئناف احلكــم بالئحــة اعتراضيــة‪ ،‬كمــا قــرر كل واحــد‬\n     ‫مــن املدعــى عليهــم األول والثانــي والثالــث قناعتــه باحلكــم‪ ،‬وقررنــا‬\n     ‫تســليم املدعــي العــام نســخة مصــورة مــن قرارنــا هــذا حــاالً‪ ،‬وجــرى‬\n     ‫إفهامــه بــأن عليــه تســليم مذكرتــه االعتراضيــة خــال ثالثــن يومــا مــن‬\n     ‫تاريــخ اليــوم‪ ،‬فــإن تأخــر عــن هــذا املوعــد ســقط حقــه يف تقــدم الالئحــة‬\n     ‫االعتراضيــة‪ ،‬وســيرفع احلكــم إلــى محكمــة االســتئناف‪ ،‬وفقــا‬\n     ‫للمادتــن الرابعــة والتســعني بعــد املائــة‪ ،‬واخلامســة والتســعني بعــد املائــة‬\n     ‫مــن نظــام اإلجــراءات اجلزائيــة‪ ..‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى‬\n                 ‫نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/03/03‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n     ‫القضايــا اخلماســية مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامة بنجــران برقم ‪341167474‬‬\n     ‫وتاريــخ ‪1434/5/12‬هـ ـ املرفــق بهــا القــرار الشــرعي الصــادر مــن‬\n     ‫أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ ...... /‬والشــيخ ‪...... /‬‬\n     ‫والشــيخ ‪ ...... /‬برقــم ‪ 3452825‬وتاريــخ ‪1434/3/2‬ه ـ اخلــاص بدعــوى‬\n     ‫املدعــي العــام ض ــد كل مــن ‪( ......3 ......-2 ...... -1/‬مينيــي اجلنســية)‬\n     ‫يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القراراملتضمــن حكــم‬\n     ‫أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ ،‬وبدراســة القــرار‬\n     ‫الشــرعي وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت‬\n     ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                      ‫وصحبــه وســلم‪.‬‬\n\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":56,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2ff62ad376d8c552b9f2dcdf813cde009ad8a8fdc0afb3e5e3726e092df64143","normalized_text_hash":"263f00c5a9538f9486bab634edb7596539fa5b78a2d6e4c4b3fa4d9e11fa2c2f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p56-3452825"},{"id":"87eb06d3-d6d6-52a5-ac9f-0d2db8df3231","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تهريب احلبوب احملظورة «االمفيتامني» -تعاطي احلبوب احملظورة -إقرار املدعى عليه -تعزير بالسجن واجللد واملنع من السفر -مراعاة قلة الكمية عند ايقاع التعزير.","document_number":"3416899","case_number":"3423461","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/19","year":"1434","subject":"مخدرات -تهريب احلبوب احملظورة «االمفيتامني» -تعاطي احلبوب احملظورة -إقرار املدعى عليه -تعزير بالسجن واجللد واملنع من السفر -مراعاة قلة الكمية عند ايقاع التعزير.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3416899 :‬تاريخه‪1434/1/19 :‬هـ‬\n                    ‫رقم الدعوى‪3423461 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3429056‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تهريــب احلبــوب احملظورة «االمفيتامني» ‪ -‬تعاطي احلبوب‬\n‫احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن‬\n                       ‫الســفر ‪ -‬مراعــاة قلــة الكميــة عنــد ايقــاع التعزيــر‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )2‬مــن املــادة (‪ )3‬واملــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن‬\n                              ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بتهريــب املخــدرات احلبــوب‬\n‫احملظــورة «االمفيتامــن»‪ ،‬مت القبــض علــى املدعــى عليــه مــن قبــل‬\n‫الضبــط اجلمركــي وعثــر بحوزتــه حبــوب االمفيتامــن ‪ ،‬أقــر املدعــى‬\n‫عليــه بالتعاطــي‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة‬\n‫املضبوطــة علــى االمفيتامــن‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى‬\n‫عليــه بالســجن ومنعــه مــن الســفر‪ ،‬حكمــت احملكمــة بثبــوت إدانــة‬\n‫املدعــى عليــه بالتهريــب وتعاطــي احلبــوب احملظــورة‪ ،‬فقــررت احملكمــة‬\n‫احلكــم علــى املدعــى عليــه بســجنه ســتني يومــا‪ ،‬وجلــده ســتني جلــدة‪،‬‬\n‫منعــه مــن الســفر خلــارج البــاد مــدة ســنتني تبــدأ بعــد انتهــاء تنفيــذ عقوبة‬\n‫الســجن‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم‬\n\n                                                                                        ‫‪70‬‬\n\f                                                  ‫مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬رئيــس احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪..........‬‬\n     ‫وتاريــخ ‪1434/01/13‬ه ـ املقيدةباحملكمــة برقــم ‪..........‬وتاريــخ‬\n     ‫‪1434/01/13‬ه ـ ففــي يــوم اإلثنــن املوافق‪1434/01/19‬ه ـ وحضــر‬\n     ‫املدعــي العــام ‪..........‬كمــا حضــر ‪،..........‬ســعودي رقــم ســجله املدنــي‬\n     ‫(‪ )..........‬وقــدم األول الئحــة دعــوى تتضمــن بــأن املدعــى عليــه البالــغ‬\n     ‫مــن العمــر (‪ )29‬عام ـاً‪ ،‬غيــر محصــن ‪ ،‬موظــف ‪ ، ....‬أوقــف بتاريــخ‬\n     ‫‪1433/11/1‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/11/8‬ه ـ اســتناد ًا للمــادة‬\n     ‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬أنــه بتاريــخ ‪1433/11/1‬ه ـ مت‬\n     ‫القبــض علــى املدعــى عليهمــن قبــل رجــال الضبــط اجلنائــي بجمــرك‬\n     ‫جســر امللــك فهــد عندمــا كان قادم ـ ًا مــن مملكــة البحريــن وكان‬\n     ‫يرافقــه ‪( ...‬لــم يثبــت جلهــة الضبــط صلتــه بالقضيــة) وعنــد قيــام املراقــب‬\n     ‫اجلمركــي بإجــراء التفتيــش علــى ســيارة املدعــى عليــه وهــو مــن نــوع‬\n     ‫‪ .....‬فضيــة اللــون حتمــل اللوحــة رقــم ( ‪ )..........‬عثــر علــى (‪ )3.5‬ثــاث‬\n     ‫حبــات ونصــف احلبــة بداخــل كيــس بالســتيكي مخفــي حتــت الفرشــة‬\n     ‫املصنعيــة للدواســات األرضيــة ملقعــد الراكــب األمامــي اثبــت التقريــر‬\n     ‫الكيمــاوي الشــرعي رقــم (‪ ).........‬وتاريــخ ‪1433/11/9‬ه ـ ايجابيتهــا‬\n     ‫عينتهــا ملــادة االمفيتامــن املنبهــة و احملظــورة‪ .‬وبســماع أقوالــه األوليــة‬\n     ‫مــن قبــل رجــال الضبــط اجلنائــي أقــر بصحــة واقعــة الضبــط وبحيازتــه‬\n     ‫ملــا مت ضبطــه وأنــه يتعاطــى احلبــوب املخــدرة واســتخدم نصــف حبــة مــن‬\n\n‫‪71‬‬\n\f‫الكميــة املضبوطــة‪ .‬وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام‬\n‫لــه بتهريــب (‪ )3.5‬ثــاث حبــات ونصفمــن حبــوب اإلمفتامــن املنبهــة‬\n‫واحملظــورة بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫املوضحــة بالــا ئحــة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n‫علــى ســوابق جنائيــة مســجله‪ .‬وحيــث أمنــا أقــدم عليــه املذكــور وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا اطلــب إثبــات مــا أســند إليــه وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة‬\n‫رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم‬\n‫عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن الــواردة بالفقــرة (‪ )1‬مــن املــادة رقــم‬\n‫(‪ )41‬مــن النظــام املشــار إليــه‪-2 .‬منعــه مــن الســفر وفــق الفقــرة رقــم(‪)1‬‬\n‫مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار إليــه‪ .‬هــذه دعــواي وبعرضهــا علــى‬\n‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف‬       ‫املدعــى عليــه أجــاب قائـ ً‬\n‫التاريــخ املذكــور بجمــرك جســر امللــك فهــد وأنــا قــادم مــن البحريــن إلــى‬\n‫الســعودية وإنــه عثــر يف ســيارتي علــى (‪ )3.5‬ثــاث حبــات ونصــف احلبــة‬\n‫مــن احلبــوب املنبهــة احملظــورة وأننــي أتعاطــى احلبــوب املنبهــة احملظــورة‬\n‫صحيــح واحلبــوب املضبوطــة تعــود لــي بقصــد التعاطــي ولكننــي تائــب‬\n‫ونــادم هكــذا أجــاب وبدراســة املعاملــة جــرى االطــاع علــى التقريــر‬\n‫الكيمــاوي وصحيفــة الســوابق املشــار لهمــا أعــاه فوجدتهــا كمــا‬\n‫ـاء علــى مــا تقــدم وحيــث تتلخــص دعــوى املدعــي‬        ‫ذكــر املدعــي العــام فبنـ ً‬\n‫العــام يف اتهــام املدعــى عليــه بتهريــب (‪ )3.5‬ثــاث حبــات ونصــف احلبــة‬\n‫مــن احلبــوب املنبهــة احملظــورة بقصــد التعاطــي وتعاطيــه لنوعهــا ويطلــب‬\n‫معاقبتــه علــى ذلــك ‪ ،‬وألن هــذه احملكمــة مختصــة بنظــر الدعــوى بنــاء‬\n‫علــى املــواد (‪ )131،128‬مــن نظــام اإلجــراءات اجلزائيــة وإلقــرار املدعــى‬\n\n\n                                                                                             ‫‪72‬‬\n\f     ‫عليــه وهــو بكامــل أهليتــه بجميــع مــا جــاء بدعــوى املدعــي العــام وألن‬\n     ‫اإلقــرار حجــة علــى املقــر وألن مــا أقــدم عليــه أفعــال محرمــة شــرع ًا ملا يف‬\n     ‫تعاطــي هــذه احلبــوب املنبهــة مــن أضــرار صحيــة بالغــة واهلل تعالــى يقــول‬\n     ‫(( وال تلقــوا بأيديكــم إلــى التهلكــة )) البقــرة ‪ 195:‬كمــا أن تهريــب‬\n     ‫وتعاطــي هــذه احلبــوب احملظــورة مجــرم نظام ـ ًا وفق ـ ًا للفقــرة (‪)2‬مــن‬\n     ‫املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات لهــذا كلــه فقــد ثبــت لديإدانــة‬\n     ‫املدعــى عليــه احلاضــر ‪ ........‬بتهريــب (‪ )3.5‬ثــاث حبــات ونصــف احلبــة‬\n     ‫مــن احلبــوب املنبهــة احملظــورة بقصــد التعاطــي وتعاطيــه لنوعهــا ونظــر ًا‬\n     ‫لقلــة الكميــة وعــدم وجــود ســوابق علــى املدعــى عليــه وملــا أبــداه مــن‬\n     ‫ـاء علــى املــواد(‪ )60،56،41‬مــن نظــام مكافحــة املخــدرات‬             ‫التوبــة وبنـ ً‬\n     ‫فقــد حكمــت بتعزيــر املدعــى عليــه للحــق العــام بجلــده ســتني جلــدة و‬\n     ‫ســجنه ســتني يومـ ًا ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني تبــدأ‬\n     ‫بعــد انتهــاء تنفيــذ عقوبــة الســجن وبإعــان احلكــم قــرر املدعــى عليــه‬\n     ‫عــدم اعتراضــه كمــا قــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة‬\n     ‫حملكمــة االســتئناف دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلــى اهلل علــى‬\n                                            ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬رئيــس احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية وبرفقهــا القراررقــم ‪ 3429056‬يف ‪1434/2/4‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم و للبيــان أحلــق يف ‪1434/2/13‬ه ـ ‪.‬‬\n     ‫احلمد هلل وحده وبعد فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة الثانية‬\n     ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة لــدى‬\n     ‫احملكمــة برقــم ‪..........‬وتاريــخ ‪1434/1/26‬ه ـ الــواردة مــن فضيلــة‬\n\n\n‫‪73‬‬\n\f‫رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ‪ ........../‬برقــم‬\n‫‪..........‬وتاريــخ ‪1434/1/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه‬\n‫املســجل برقــم ‪..........‬وتاريــخ ‪1434/1/19‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n‫العــام ضــد‪........../‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/3‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪74‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":70,"source_page_end":74,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2be1684cd729e763c94a095ecaa60e7cc9fe29987df2b999be0c4ff0a895f1d7","normalized_text_hash":"4e841142dc0a91416600b8fb4228cadf64c95147f13f90013ddc74eda50c5298","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p70-3416899"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

